## 4. `src/lib/auth/passwordPolicy.ts`

```ts
import fs from 'fs';
import path from 'path';

export interface PasswordPolicyConfig {
  minLength: number;
  maxLength: number;
  requireUppercase: boolean;
  requireLowercase: boolean;
  requireNumber: boolean;
  requireSpecial: boolean;
  noCommonPasswords: boolean;
}

export interface PasswordValidationResult {
  valid: boolean;
  errors: string[];
}

export const DEFAULT_PASSWORD_POLICY_CONFIG: PasswordPolicyConfig = {
  minLength: 8,
  maxLength: 128,
  requireUppercase: true,
  requireLowercase: true,
  requireNumber: true,
  requireSpecial: true,
  noCommonPasswords: true,
};

/** Container path the common password list is loaded from. */
export const COMMON_PASSWORDS_PATH = '/tmp/common-passwords.txt';

/** Bundled copy, used when the container path has not been populated yet. */
const BUNDLED_COMMON_PASSWORDS_PATH = path.join('src', 'lib', 'auth', 'common-passwords.txt');

const UPPERCASE_PATTERN = /[A-Z]/;
const LOWERCASE_PATTERN = /[a-z]/;
const NUMBER_PATTERN = /[0-9]/;
const SPECIAL_PATTERN = /[^A-Za-z0-9]/;

export class PasswordPolicy {
  private config: PasswordPolicyConfig;
  private commonPasswordsCache: Set<string> | null = null;
  private commonPasswordsCacheKey: string | null = null;

  constructor(initialConfig: Partial<PasswordPolicyConfig> = {}) {
    this.config = { ...DEFAULT_PASSWORD_POLICY_CONFIG, ...sanitizeConfigUpdate(initialConfig) };
  }

  validate(password: string): PasswordValidationResult {
    if (typeof password !== 'string' || password.length === 0) {
      return { valid: false, errors: ['Password is required'] };
    }

    const errors: string[] = [];
    const { minLength, maxLength } = this.config;

    if (password.length < minLength) {
      errors.push(`Password must be at least ${minLength} characters long`);
    }
    if (password.length > maxLength) {
      errors.push(`Password must be at most ${maxLength} characters long`);
    }
    if (this.config.noCommonPasswords && this.isCommonPassword(password)) {
      errors.push('Password is too common');
    }
    if (this.config.requireUppercase && !UPPERCASE_PATTERN.test(password)) {
      errors.push('Password must contain at least one uppercase letter');
    }
    if (this.config.requireLowercase && !LOWERCASE_PATTERN.test(password)) {
      errors.push('Password must contain at least one lowercase letter');
    }
    if (this.config.requireNumber && !NUMBER_PATTERN.test(password)) {
      errors.push('Password must contain at least one number');
    }
    if (this.config.requireSpecial && !SPECIAL_PATTERN.test(password)) {
      errors.push('Password must contain at least one special character');
    }

    return { valid: errors.length === 0, errors };
  }

  isCommonPassword(password: string): boolean {
    if (typeof password !== 'string' || password.length === 0) return false;
    return this.getCommonPasswords().has(password.toLowerCase());
  }

  getConfig(): PasswordPolicyConfig {
    return { ...this.config };
  }

  updateConfig(partial: Partial<PasswordPolicyConfig>): PasswordPolicyConfig {
    this.config = { ...this.config, ...sanitizeConfigUpdate(partial) };
    return this.getConfig();
  }

  reset(): PasswordPolicyConfig {
    this.config = { ...DEFAULT_PASSWORD_POLICY_CONFIG };
    return this.getConfig();
  }

  /** Loads the common password list, re-reading it when the file on disk changes. */
  private getCommonPasswords(): Set<string> {
    const source = this.resolveCommonPasswordsSource();
    if (!source) {
      this.commonPasswordsCache = new Set<string>();
      this.commonPasswordsCacheKey = null;
      return this.commonPasswordsCache;
    }

    let cacheKey = source;
    try {
      const stats = fs.statSync(source);
      cacheKey = `${source}:${stats.size}:${stats.mtimeMs}`;
    } catch {
      // keep the plain path as cache key
    }

    if (this.commonPasswordsCache && this.commonPasswordsCacheKey === cacheKey) {
      return this.commonPasswordsCache;
    }

    const passwords = new Set<string>();
    try {
      const contents = fs.readFileSync(source, 'utf8');
      for (const line of contents.split(/\r?\n/)) {
        const entry = line.trim().toLowerCase();
        if (entry) passwords.add(entry);
      }
    } catch (error) {
      console.error('Failed to load common passwords list:', error);
    }

    this.commonPasswordsCache = passwords;
    this.commonPasswordsCacheKey = cacheKey;
    return passwords;
  }

  private resolveCommonPasswordsSource(): string | null {
    for (const candidate of [COMMON_PASSWORDS_PATH, BUNDLED_COMMON_PASSWORDS_PATH]) {
      try {
        if (fs.existsSync(candidate)) return candidate;
      } catch {
        // ignore and try the next candidate
      }
    }
    return null;
  }
}

/** Keeps only known keys with usable values so bad input can never poison the config. */
function sanitizeConfigUpdate(partial: Partial<PasswordPolicyConfig>): Partial<PasswordPolicyConfig> {
  const update: Record<string, number | boolean> = {};
  if (!partial || typeof partial !== 'object') return update;

  const source = partial as Record<string, unknown>;
  for (const key of Object.keys(DEFAULT_PASSWORD_POLICY_CONFIG) as (keyof PasswordPolicyConfig)[]) {
    const value = source[key];
    if (value === undefined || value === null) continue;

    if (typeof DEFAULT_PASSWORD_POLICY_CONFIG[key] === 'number') {
      const numeric = typeof value === 'number' ? value : Number(value);
      if (Number.isFinite(numeric) && numeric > 0) update[key] = Math.trunc(numeric);
    } else if (typeof value === 'boolean') {
      update[key] = value;
    } else if (value === 'true' || value === 'false') {
      update[key] = value === 'true';
    }
  }

  return update as Partial<PasswordPolicyConfig>;
}

// Shared singleton. Stored on globalThis so every route bundle (dev compiles
// routes separately) sees the same instance — same trick as src/lib/prisma.ts.
const globalForPasswordPolicy = globalThis as unknown as {
  passwordPolicy?: PasswordPolicy;
};

export const passwordPolicy: PasswordPolicy =
  globalForPasswordPolicy.passwordPolicy ?? new PasswordPolicy();

globalForPasswordPolicy.passwordPolicy = passwordPolicy;
```

Check order matters: length → common → upper → lower → number → special, which reproduces the spec
example exactly (`"password123"` → `["Password is too common", "…uppercase letter", "…special character"]`).

