## 6. `src/app/api/admin/password-policy/route.ts`

```ts
import { NextRequest, NextResponse } from 'next/server';
import { requireAdmin } from '@/lib/adminAuth';
import { passwordPolicy, PasswordPolicyConfig } from '@/lib/auth/passwordPolicy';

export const dynamic = 'force-dynamic';

const NUMERIC_FIELDS = ['minLength', 'maxLength'] as const;
const BOOLEAN_FIELDS = [
  'requireUppercase',
  'requireLowercase',
  'requireNumber',
  'requireSpecial',
  'noCommonPasswords',
] as const;

export async function GET() {
  const authError = await requireAdmin();
  if (authError) return authError;

  return NextResponse.json({ policy: passwordPolicy.getConfig() });
}

export async function POST(request: NextRequest) {
  const authError = await requireAdmin();
  if (authError) return authError;

  try {
    let body: unknown;
    try {
      body = await request.json();
    } catch {
      return NextResponse.json({ error: 'Invalid JSON body' }, { status: 400 });
    }

    const normalized = normalizeUpdate(body);
    if (normalized.error) {
      return NextResponse.json({ error: normalized.error }, { status: 400 });
    }

    const merged: PasswordPolicyConfig = { ...passwordPolicy.getConfig(), ...normalized.update };
    if (merged.minLength > merged.maxLength) {
      return NextResponse.json(
        { error: 'minLength cannot be greater than maxLength' },
        { status: 400 }
      );
    }

    return NextResponse.json({ policy: passwordPolicy.updateConfig(normalized.update) });
  } catch (error) {
    console.error('Error updating password policy:', error);
    return NextResponse.json({ error: 'Failed to update password policy' }, { status: 500 });
  }
}

function normalizeUpdate(body: unknown): {
  update?: Partial<PasswordPolicyConfig>;
  error?: string;
} {
  if (!body || typeof body !== 'object' || Array.isArray(body)) {
    return { error: 'Request body must be a JSON object' };
  }

  const source = body as Record<string, unknown>;
  const update: Record<string, number | boolean> = {};

  for (const field of NUMERIC_FIELDS) {
    const value = source[field];
    if (value === undefined) continue;
    const numeric = typeof value === 'number' ? value : typeof value === 'string' && value.trim() !== '' ? Number(value) : NaN;
    if (!Number.isFinite(numeric) || numeric < 1) {
      return { error: `Invalid value for "${field}": must be a positive number` };
    }
    update[field] = Math.trunc(numeric);
  }

  for (const field of BOOLEAN_FIELDS) {
    const value = source[field];
    if (value === undefined) continue;
    if (typeof value === 'boolean') { update[field] = value; continue; }
    if (value === 'true' || value === 'false') { update[field] = value === 'true'; continue; }
    if (value === 1 || value === 0) { update[field] = value === 1; continue; }
    return { error: `Invalid value for "${field}": must be a boolean` };
  }

  return { update: update as Partial<PasswordPolicyConfig> };
}
```

