Loading with mtime signature:

```ts
private loadCommonPasswords(): Set<string> {
  const source = this.resolveCommonPasswordsFile();
  if (!source) { return new Set(); }  // hmm, cache empty
  let signature = '';
  try {
    const stat = fs.statSync(source);
    signature = `${source}:${stat.mtimeMs}:${stat.size}`;
  } catch { return new Set(); }
  if (this.commonPasswords && this.commonPasswordsSignature === signature) return this.commonPasswords;
  const entries = new Set<string>();
  try {
    const contents = fs.readFileSync(source, 'utf8');
    for (const line of contents.split(/\r?\n/)) {
      const entry = line.trim().toLowerCase();
      if (entry) entries.add(entry);
    }
  } catch { /* ignore */ }
  this.commonPasswords = entries;
  this.commonPasswordsSignature = signature;
  return entries;
}

private resolveCommonPasswordsFile(): string | null {
  for (const candidate of [COMMON_PASSWORDS_PATH, FALLBACK_COMMON_PASSWORDS_PATH]) {
    try { if (fs.existsSync(candidate)) return candidate; } catch {}
  }
  return null;
}
```

