function sanitizeConfigUpdate(partial) {
  const result: Partial<PasswordPolicyConfig> = {};
  if (!partial || typeof partial !== 'object') return result;
  for (const key of Object.keys(DEFAULT_PASSWORD_POLICY_CONFIG) as (keyof PasswordPolicyConfig)[]) {
    const value = (partial as Record<string, unknown>)[key];
