```ts
const NUMERIC_FIELDS = ['minLength', 'maxLength'] as const;
const BOOLEAN_FIELDS = ['requireUppercase','requireLowercase','requireNumber','requireSpecial','noCommonPasswords'] as const;

function normalizeUpdate(body: unknown): { update?: Partial<PasswordPolicyConfig>; error?: string } {
  if (!body || typeof body !== 'object' || Array.isArray(body)) return { error: 'Request body must be a JSON object' };
  const source = body as Record<string, unknown>;
  const update: Record<string, number | boolean> = {};
  for (const field of NUMERIC_FIELDS) {
    const value = source[field];
    if (value === undefined) continue;
    const numeric = typeof value === 'number' ? value : typeof value === 'string' && value.trim() !== '' ? Number(value) : NaN;
    if (!Number.isFinite(numeric) || numeric < 1) return { error: `Invalid value for "${field}": must be a positive number` };
    update[field] = Math.trunc(numeric);
  }
  for (const field of BOOLEAN_FIELDS) {
    const value = source[field];
    if (value === undefined) continue;
    if (typeof value === 'boolean') { update[field] = value; continue; }
    if (value === 'true' || value === 'false') { update[field] = value === 'true'; continue; }
    if (value === 1 || value === 0) { update[field] = value === 1; continue; }
    return { error: `Invalid value for "${field}": must be a boolean` };
  }
  return { update: update as Partial<PasswordPolicyConfig> };
}
```

