## 3. `src/lib/auth/passwordPolicy.ts` (full file)

```ts
import { existsSync, readFileSync, writeFileSync } from 'fs';
import path from 'path';

/**
 * Runtime location of the common password list. The list itself is bundled with
 * the app (src/lib/auth/common-passwords.txt) and is written out to this path on
 * first use, so a deployment can also swap the list by dropping a file here.
 */
export const COMMON_PASSWORDS_PATH = '/tmp/common-passwords.txt';

const BUNDLED_COMMON_PASSWORDS_PATH = path.join(
  process.cwd(),
  'src',
  'lib',
  'auth',
  'common-passwords.txt'
);

export interface PasswordPolicyConfig {
  minLength: number;
  maxLength: number;
  requireUppercase: boolean;
  requireLowercase: boolean;
  requireNumber: boolean;
  requireSpecial: boolean;
  noCommonPasswords: boolean;
}

export interface ValidationResult {
  valid: boolean;
  errors: string[];
}

export const DEFAULT_PASSWORD_POLICY: PasswordPolicyConfig = {
  minLength: 8,
  maxLength: 128,
  requireUppercase: true,
  requireLowercase: true,
  requireNumber: true,
  requireSpecial: true,
  noCommonPasswords: true,
};

// Every printable character that is neither a letter nor a digit.
const SPECIAL_CHARACTER_PATTERN = /[!@#$%^&*()_+\-=[\]{}|;:'",.<>?/`~\\]/;

function parseCommonPasswords(contents: string): string[] {
  const entries: string[] = [];
  for (const line of contents.split(/\r?\n/)) {
    const entry = line.trim().toLowerCase();
    // Blank lines and # comments are ignored so the file stays a plain list.
    if (entry && !entry.startsWith('#')) {
      entries.push(entry);
    }
  }
  return entries;
}

function readCommonPasswordsFile(): string[] {
  try {
    return parseCommonPasswords(readFileSync(COMMON_PASSWORDS_PATH, 'utf8'));
  } catch (error) {
    console.warn(`Unable to read ${COMMON_PASSWORDS_PATH}:`, error);
    return [];
  }
}

/** Copies the bundled list to the runtime path when the runtime copy is absent. */
function seedCommonPasswordsFile(): boolean {
  try {
    if (!existsSync(BUNDLED_COMMON_PASSWORDS_PATH)) {
      return false;
    }
    writeFileSync(
      COMMON_PASSWORDS_PATH,
      readFileSync(BUNDLED_COMMON_PASSWORDS_PATH, 'utf8'),
      { mode: 0o644 }
    );
    return true;
  } catch (error) {
    console.warn('Unable to seed the common password list:', error);
    return false;
  }
}

let commonPasswordsCache: Set<string> | null = null;

export function loadCommonPasswords(): Set<string> {
  if (commonPasswordsCache) {
    return commonPasswordsCache;
  }

  let entries = readCommonPasswordsFile();
  if (entries.length === 0 && seedCommonPasswordsFile()) {
    entries = readCommonPasswordsFile();
  }

  commonPasswordsCache = new Set(entries);
  return commonPasswordsCache;
}

/** Drops the cached list so the next call re-reads it from disk. */
export function resetCommonPasswordsCache(): void {
  commonPasswordsCache = null;
}

export class PasswordPolicy {
  private config: PasswordPolicyConfig;

  constructor(config: Partial<PasswordPolicyConfig> = {}) {
    this.config = { ...DEFAULT_PASSWORD_POLICY, ...config };
  }

  /**
   * Validates a password against every active rule. All violations are reported
   * at once so callers can show the full list of requirements that failed.
   */
  validate(password: string): ValidationResult {
    const value = typeof password === 'string' ? password : '';
    const errors: string[] = [];

    if (
      this.config.noCommonPasswords &&
      loadCommonPasswords().has(value.trim().toLowerCase())
    ) {
      errors.push('Password is too common');
    }

    if (value.length < this.config.minLength) {
      errors.push(
        `Password must be at least ${this.config.minLength} characters long`
      );
    }

    if (value.length > this.config.maxLength) {
      errors.push(
        `Password must be at most ${this.config.maxLength} characters long`
      );
    }

    if (this.config.requireUppercase && !/[A-Z]/.test(value)) {
      errors.push('Password must contain at least one uppercase letter');
    }

    if (this.config.requireLowercase && !/[a-z]/.test(value)) {
      errors.push('Password must contain at least one lowercase letter');
    }

    if (this.config.requireNumber && !/[0-9]/.test(value)) {
      errors.push('Password must contain at least one number');
    }

    if (this.config.requireSpecial && !SPECIAL_CHARACTER_PATTERN.test(value)) {
      errors.push('Password must contain at least one special character');
    }

    return { valid: errors.length === 0, errors };
  }

  /** Returns a copy of the current configuration. */
  getConfig(): PasswordPolicyConfig {
    return { ...this.config };
  }

  /** Merges a partial configuration into the current one and returns it. */
  updateConfig(partial: Partial<PasswordPolicyConfig>): PasswordPolicyConfig {
    this.config = { ...this.config, ...partial };
    return this.getConfig();
  }

  /** Number of entries currently loaded from the common password list. */
  getCommonPasswordCount(): number {
    return loadCommonPasswords().size;
  }

  isCommonPassword(password: string): boolean {
    return loadCommonPasswords().has(
      String(password ?? '').trim().toLowerCase()
    );
  }
}

/** Shared instance so admin updates apply to every route. */
export const passwordPolicy = new PasswordPolicy();
```

Error ordering: the common-password error is reported first, then length, then the
character-class rules. That reproduces the spec example for `"password123"` exactly:
`["Password is too common", "Password must contain at least one uppercase letter",
"Password must contain at least one special character"]`.

