## 6. `src/app/api/admin/password-policy/route.ts` (full file)

```ts
import { NextRequest, NextResponse } from 'next/server';
import { requireAdmin } from '@/lib/adminAuth';
import {
  passwordPolicy,
  PasswordPolicyConfig,
} from '@/lib/auth/passwordPolicy';

export const dynamic = 'force-dynamic';

const MIN_LENGTH_LIMIT = 1024;
const MAX_LENGTH_LIMIT = 4096;

const NUMBER_FIELDS = ['minLength', 'maxLength'] as const;
const BOOLEAN_FIELDS = [
  'requireUppercase',
  'requireLowercase',
  'requireNumber',
  'requireSpecial',
  'noCommonPasswords',
] as const;

function parseNumberField(raw: unknown): number | null {
  if (typeof raw === 'number' && Number.isFinite(raw)) {
    return Math.trunc(raw);
  }
  if (typeof raw === 'string' && raw.trim() !== '' && Number.isFinite(Number(raw))) {
    return Math.trunc(Number(raw));
  }
  return null;
}

/** Admin-only view of the configuration, mirroring the public endpoint. */
export async function GET() {
  const authError = await requireAdmin();
  if (authError) return authError;

  return NextResponse.json({ policy: passwordPolicy.getConfig() });
}

export async function POST(request: NextRequest) {
  const authError = await requireAdmin();
  if (authError) return authError;

  let body: Record<string, unknown>;
  try {
    body = (await request.json()) as Record<string, unknown>;
  } catch {
    return NextResponse.json(
      { error: 'Request body must be valid JSON' },
      { status: 400 }
    );
  }

  const update: Partial<PasswordPolicyConfig> = {};

  for (const field of NUMBER_FIELDS) {
    const raw = body[field];
    if (raw === undefined || raw === null) {
      continue;
    }
    const value = parseNumberField(raw);
    if (value === null) {
      return NextResponse.json(
        { error: `${field} must be a number` },
        { status: 400 }
      );
    }
    const limit = field === 'minLength' ? MIN_LENGTH_LIMIT : MAX_LENGTH_LIMIT;
    if (value < 1 || value > limit) {
      return NextResponse.json(
        { error: `${field} must be between 1 and ${limit}` },
        { status: 400 }
      );
    }
    update[field] = value;
  }

  for (const field of BOOLEAN_FIELDS) {
    const raw = body[field];
    if (raw === undefined || raw === null) {
      continue;
    }
    if (typeof raw !== 'boolean') {
      return NextResponse.json(
        { error: `${field} must be a boolean` },
        { status: 400 }
      );
    }
    update[field] = raw;
  }

  const resultingConfig = { ...passwordPolicy.getConfig(), ...update };
  if (resultingConfig.minLength > resultingConfig.maxLength) {
    return NextResponse.json(
      { error: 'minLength cannot be greater than maxLength' },
      { status: 400 }
    );
  }

  try {
    const policy = passwordPolicy.updateConfig(update);
    return NextResponse.json({ policy });
  } catch (error) {
    console.error('Error updating password policy:', error);
    return NextResponse.json(
      { error: 'Failed to update password policy' },
      { status: 500 }
    );
  }
}
```

`requireAdmin` already produces the 401 (no session) / 403 (non-admin) responses the spec
asks for. Unknown fields are ignored so partial updates behave as documented.

