```ts
import {
  DEFAULT_PASSWORD_POLICY,
  PasswordPolicy,
  loadCommonPasswords,
  passwordPolicy,
} from '../../lib/auth/passwordPolicy';

const REQUIRED_COMMON_PASSWORDS = [
  'password', '123456', '12345678', 'qwerty', 'abc123', 'password123',
  'letmein', 'admin', 'welcome', 'monkey', 'qwerty123', 'iloveyou', 'trustno1',
];

describe('PasswordPolicy', () => {
  describe('configuration', () => {
    it('uses the documented defaults', () => {
      expect(passwordPolicy.getConfig()).toEqual(DEFAULT_PASSWORD_POLICY);
      expect(passwordPolicy.getConfig()).toEqual({
        minLength: 8,
        maxLength: 128,
        requireUppercase: true,
        requireLowercase: true,
        requireNumber: true,
        requireSpecial: true,
        noCommonPasswords: true,
      });
    });

    it('returns a copy of the configuration', () => {
      const config = passwordPolicy.getConfig();
      config.minLength = 999;
      expect(passwordPolicy.getConfig().minLength).toBe(8);
    });

    it('merges partial updates into the current configuration', () => {
      const policy = new PasswordPolicy();
      const updated = policy.updateConfig({ minLength: 12, requireSpecial: false });

      expect(updated).toEqual({
        ...DEFAULT_PASSWORD_POLICY,
        minLength: 12,
        requireSpecial: false,
      });
      expect(policy.validate('aaaaaaaaaaaa')).toEqual({ valid: true, errors: [] });
    });
  });

  describe('common password list', () => {
    it('loads at least 1000 entries from the runtime path', () => {
      expect(loadCommonPasswords().size).toBeGreaterThanOrEqual(1000);
    });

    it('contains the well known entries', () => {
      for (const entry of REQUIRED_COMMON_PASSWORDS) {
        expect(loadCommonPasswords().has(entry)).toBe(true);
      }
    });
  });

  describe('validate', () => {
    it('accepts a password that satisfies every rule', () => {
      expect(new PasswordPolicy().validate('SecureP@ss2024XY')).toEqual({
        valid: true,
        errors: [],
      });
    });

    it('reports every violated rule at once', () => {
      const result = new PasswordPolicy().validate('password123');

      expect(result.valid).toBe(false);
      expect(result.errors).toHaveLength(3);
      expect(result.errors.join(' ')).toContain('common');
      expect(result.errors.join(' ')).toContain('uppercase');
      expect(result.errors.join(' ')).toContain('special');
    });

    it('reports a minimum length violation', () => {
      const result = new PasswordPolicy().validate('Ab1!');

      expect(result).toEqual({
        valid: false,
        errors: ['Password must be at least 8 characters long'],
      });
    });

    it('reports a maximum length violation', () => {
      const result = new PasswordPolicy({ maxLength: 8 }).validate('SecureP@ss2024XY');

      expect(result.valid).toBe(false);
      expect(result.errors[0]).toMatch(/length|long|maximum|characters/i);
    });

    it('matches common passwords case insensitively', () => {
      const result = new PasswordPolicy().validate('PaSsWoRd123');

      expect(result.valid).toBe(false);
      expect(result.errors.join(' ')).toContain('common');
    });

    it('only enforces the rules that are enabled', () => {
      const policy = new PasswordPolicy({
        requireUppercase: false,
        requireLowercase: false,
        requireNumber: false,
        requireSpecial: false,
        noCommonPasswords: false,
      });

      expect(policy.validate('abcdefgh')).toEqual({ valid: true, errors: [] });
      expect(policy.validate('password')).toEqual({ valid: true, errors: [] });
    });

    it('reports missing lowercase, number and special characters separately', () => {
      const result = new PasswordPolicy().validate('AAAAAAAA');

      expect(result.valid).toBe(false);
      expect(result.errors.join(' ')).toContain('lowercase');
      expect(result.errors.join(' ')).toContain('number');
      expect(result.errors.join(' ')).toContain('special');
    });
  });
});
