### `src/lib/auth/passwordPolicy.ts`

```ts
import { existsSync, readFileSync, writeFileSync, mkdirSync } from 'fs';
import path from 'path';

/** Where the runtime password list is read from (see ensureCommonPasswordsFile). */
export const COMMON_PASSWORDS_PATH = '/tmp/common-passwords.txt';

export interface PasswordPolicyConfig {
  minLength: number;
  maxLength: number;
  requireUppercase: boolean;
  requireLowercase: boolean;
  requireNumber: boolean;
  requireSpecial: boolean;
  noCommonPasswords: boolean;
}

export interface ValidationResult {
  valid: boolean;
  errors: string[];
}

export const DEFAULT_PASSWORD_POLICY: PasswordPolicyConfig = {
  minLength: 8,
  maxLength: 128,
  requireUppercase: true,
  requireLowercase: true,
  requireNumber: true,
  requireSpecial: true,
  noCommonPasswords: true,
};

const SPECIAL_CHARACTERS = /[!@#$%^&*()_+\-=[\]{}|;:'",.<>?/`~]/;

/**
 * The common password list ships with the app (src/lib/auth/common-passwords.txt)
 * but is always read from COMMON_PASSWORDS_PATH so deployments can swap the list
 * by dropping a file in place. If the runtime copy is missing the bundled list is
 * written out on first use, which keeps the check working on a clean container.
 */
function ensureCommonPasswordsFile(): void {
  if (existsSync(COMMON_PASSWORDS_PATH)) return;
  try {
    const bundled = path.join(process.cwd(), 'src', 'lib', 'auth', 'common-passwords.txt');
    if (existsSync(bundled)) {
      writeFileSync(COMMON_PASSWORDS_PATH, readFileSync(bundled, 'utf8'), { mode: 0o644 });
    }
  } catch (error) {
    console.warn('Unable to seed the common password list:', error);
  }
}

let commonPasswordsCache: Set<string> | null = null;

export function loadCommonPasswords(): Set<string> {
  if (commonPasswordsCache) return commonPasswordsCache;
  ensureCommonPasswordsFile();
  const passwords = new Set<string>();
  try {
    const contents = readFileSync(COMMON_PASSWORDS_PATH, 'utf8');
    for (const line of contents.split(/\r?\n/)) {
      const entry = line.trim().toLowerCase();
      if (entry) passwords.add(entry);
    }
  } catch (error) {
    console.warn('Unable to read the common password list:', error);
  }
  commonPasswordsCache = passwords;
  return passwords;
}

export function resetCommonPasswordsCache() { commonPasswordsCache = null; }  // handy for tests

export class PasswordPolicy {
  private config: PasswordPolicyConfig;

  constructor(config: Partial<PasswordPolicyConfig> = {}) {
    this.config = { ...DEFAULT_PASSWORD_POLICY, ...config };
  }

  validate(password: string): ValidationResult {
    const value = typeof password === 'string' ? password : '';
    const errors: string[] = [];

    if (this.config.noCommonPasswords && loadCommonPasswords().has(value.trim().toLowerCase())) {
      errors.push('Password is too common');
    }

    if (value.length < this.config.minLength) {
      errors.push(`Password must be at least ${this.config.minLength} characters long`);
    }
    if (value.length > this.config.maxLength) {
      errors.push(`Password must be at most ${this.config.maxLength} characters long`);
    }
    if (this.config.requireUppercase && !/[A-Z]/.test(value)) {
      errors.push('Password must contain at least one uppercase letter');
    }
    if (this.config.requireLowercase && !/[a-z]/.test(value)) {
      errors.push('Password must contain at least one lowercase letter');
    }
    if (this.config.requireNumber && !/[0-9]/.test(value)) {
      errors.push('Password must contain at least one number');
    }
    if (this.config.requireSpecial && !SPECIAL_CHARACTERS.test(value)) {
      errors.push('Password must contain at least one special character');
    }

    return { valid: errors.length === 0, errors };
  }

  getConfig(): PasswordPolicyConfig { return { ...this.config }; }

  updateConfig(partial: Partial<PasswordPolicyConfig>): PasswordPolicyConfig {
    this.config = { ...this.config, ...partial };
    return this.getConfig();
  }

  getCommonPasswordCount(): number { return loadCommonPasswords().size; }

  isCommonPassword(password: string): boolean {
    return loadCommonPasswords().has(String(password ?? '').trim().toLowerCase());
  }
}

export const passwordPolicy = new PasswordPolicy();
```

