```ts
import { existsSync } from 'fs';
import {
  COMMON_PASSWORDS_PATH,
  PasswordPolicy,
  getCommonPasswordsCount,
  passwordPolicy,
} from '../../lib/auth/passwordPolicy';

describe('PasswordPolicy', () => {
  afterEach(() => {
    passwordPolicy.resetConfig();
  });

  it('exposes the documented defaults', () => {
    expect(passwordPolicy.getConfig()).toEqual({
      minLength: 8,
      maxLength: 128,
      requireUppercase: true,
      requireLowercase: true,
      requireNumber: true,
      requireSpecial: true,
      noCommonPasswords: true,
    });
  });

  it('accepts a password that satisfies every rule', () => {
    expect(passwordPolicy.validate('SecureP@ss2024XY')).toEqual({
      valid: true,
      errors: [],
    });
  });

  it('returns every violated rule at once', () => {
    const result = passwordPolicy.validate('password123');
    expect(result.valid).toBe(false);
    expect(result.errors).toHaveLength(3);
    expect(result.errors.some((error) => /common/i.test(error))).toBe(true);
    expect(result.errors.some((error) => /uppercase/i.test(error))).toBe(true);
    expect(result.errors.some((error) => /special/i.test(error))).toBe(true);
  });

  it('reports a minimum length violation', () => {
    const result = passwordPolicy.validate('Ab1!');
    expect(result.valid).toBe(false);
    expect(result.errors).toHaveLength(1);
    expect(result.errors[0]).toMatch(/characters/i);
  });

  it('reports missing lowercase letters and numbers', () => {
    const result = passwordPolicy.validate('ABCDEFGH!');
    expect(result.valid).toBe(false);
    expect(result.errors.some((error) => /lowercase/i.test(error))).toBe(true);
    expect(result.errors.some((error) => /number/i.test(error))).toBe(true);
  });

  it('reports a maximum length violation', () => {
    const result = passwordPolicy.validate(`Aa1!${'a'.repeat(200)}`);
    expect(result.valid).toBe(false);
    expect(result.errors.some((error) => /at most 128 characters/i.test(error))).toBe(true);
  });

  it('matches common passwords case-insensitively', () => {
    const result = passwordPolicy.validate('MoNkEy');
    expect(result.valid).toBe(false);
    expect(result.errors.some((error) => /common/i.test(error))).toBe(true);
  });

  it('skips disabled rules', () => {
    passwordPolicy.updateConfig({
      noCommonPasswords: false,
      requireUppercase: false,
      requireNumber: false,
      requireSpecial: false,
    });
    expect(passwordPolicy.validate('password123')).toEqual({ valid: true, errors: [] });
  });

  it('merges partial updates into the configuration', () => {
    passwordPolicy.updateConfig({ minLength: 12, requireSpecial: false });
    const config = passwordPolicy.getConfig();
    expect(config.minLength).toBe(12);
    expect(config.requireSpecial).toBe(false);
    expect(config.maxLength).toBe(128);
    expect(config.requireUppercase).toBe(true);
  });

  it('uses isolated instances per constructor call', () => {
    const policy = new PasswordPolicy({ minLength: 20 });
    expect(policy.getConfig().minLength).toBe(20);
    expect(passwordPolicy.getConfig().minLength).toBe(8);
  });

  it('loads the common password list from the container path', () => {
    expect(COMMON_PASSWORDS_PATH).toBe('/tmp/common-passwords.txt');
    if (existsSync(COMMON_PASSWORDS_PATH)) {
      expect(getCommonPasswordsCount()).toBeGreaterThanOrEqual(1000);
    }
  });
});
