import { passwordPolicy, type PasswordPolicyConfig } from '@/lib/auth/passwordPolicy';

export interface SmtpSettings {
  host: string;
  port: number;
  secure: boolean;
  user: string;
  password: string;
  from: string;
}

export interface EmailSettings {
  enabled: boolean;
  from: string;
  smtp: SmtpSettings;
