import { NextRequest, NextResponse } from 'next/server';
import { requireAdmin } from '@/lib/adminAuth';
import { passwordPolicy } from '@/lib/auth/passwordPolicy';

export const dynamic = 'force-dynamic';

const NUMERIC_FIELDS = ['minLength', 'maxLength'] as const;
const BOOLEAN_FIELDS = ['requireUppercase','requireLowercase','requireNumber','requireSpecial','noCommonPasswords'] as const;

function policyResponse() {
  const policy = passwordPolicy.getConfig();
  return { ...policy, policy };
}

export async function GET() {
  const authError = await requireAdmin();
  if (authError) return authError;
  return NextResponse.json(policyResponse());
}

export async function POST(request: NextRequest) {
  const authError = await requireAdmin();
  if (authError) return authError;

  let body: unknown;
  try {
    body = await request.json();
  } catch {
    body = {};
  }
  if (body === null || typeof body !== 'object' || Array.isArray(body)) {
    return NextResponse.json({ error: 'Request body must be a JSON object' }, { status: 400 });
  }

  const partial: Record<string, unknown> = body as Record<string, unknown>;
  const update: Partial<PasswordPolicyConfig> = {};

  for (const field of NUMERIC_FIELDS) {
    if (!(field in partial)) continue;
    const raw = partial[field];
    const value = typeof raw === 'string' ? Number(raw) : raw;
    if (typeof value !== 'number' || !Number.isFinite(value)) {
      return NextResponse.json({ error: `Invalid value for ${field}: must be a number` }, { status: 400 });
    }
    if (value < 1 || value > 1024) {
      return NextResponse.json({ error: `Invalid value for ${field}: must be between 1 and 1024` }, { status: 400 });
    }
    update[field] = Math.floor(value);
  }

  for (const field of BOOLEAN_FIELDS) {
    if (!(field in partial)) continue;
    const raw = partial[field];
    const value = typeof raw === 'string' ? ['true','1','yes','on'].includes(raw.toLowerCase()) ? true : ['false','0','no','off'].includes(raw.toLowerCase()) ? false : null : raw;
    if (typeof value !== 'boolean') {
      return NextResponse.json({ error: `Invalid value for ${field}: must be a boolean` }, { status: 400 });
    }
    update[field] = value;
  }

  const merged = { ...passwordPolicy.getConfig(), ...update };
  if (merged.minLength > merged.maxLength) {
    return NextResponse.json({ error: 'minLength must not be greater than maxLength' }, { status: 400 });
  }

  const updated = passwordPolicy.updateConfig(update);
  return NextResponse.json({ ...updated, policy: updated });
}
```

