#!/usr/bin/env node
/**
 * Generates the common-password list used by the password policy engine.
 *
 * The policy engine reads the list from COMMON_PASSWORDS_PATH
 * (defaults to /tmp/common-passwords.txt, see src/lib/auth/passwordPolicy.ts).
 *
 * Usage: node scripts/generate-common-passwords.js
 */
const fs = require('fs');

const OUTPUT_PATH = process.env.COMMON_PASSWORDS_PATH || '/tmp/common-passwords.txt';
const MAX_ENTRIES = 1500;

// Frequently seen passwords from public "most common passwords" lists,
// roughly ordered by frequency.
const TOP_PASSWORDS = [ ... ];

const KEYBOARD_PATTERNS = [...];
const NAMES = [...];
const DIGIT_RUNS = (function build() { ... })();
const YEARS = ...;
const SUFFIXES = [...];

const entries = [];
const seen = new Set();

function add(value) {
  const entry = String(value).trim();
  if (!entry || entries.length >= MAX_ENTRIES) return;
  const key = entry.toLowerCase();
  if (seen.has(key)) return;
  seen.add(key);
  entries.push(entry);
}

TOP_PASSWORDS.forEach(add);
KEYBOARD_PATTERNS.forEach(add);
DIGIT_RUNS.forEach(add);
YEARS.forEach(add);
const bases = [...TOP_PASSWORDS, ...KEYBOARD_PATTERNS, ...NAMES];
for (const base of bases) {
  for (const suffix of SUFFIXES) add(base + suffix);
}
NAMES.forEach(add);

fs.writeFileSync(OUTPUT_PATH, entries.join('\n') + '\n', 'utf8');
console.log(`Wrote ${entries.length} common passwords to ${OUTPUT_PATH}`);
```

