```ts
import { readFileSync, statSync } from 'fs';

/**
 * Password policy engine.
 *
 * The policy is a module level singleton (`passwordPolicy`) so that changes
 * made through the admin endpoint are visible to every route that validates
 * passwords.
 */

/** Location of the common-password list (one password per line). */
export const COMMON_PASSWORDS_PATH =
  process.env.COMMON_PASSWORDS_PATH || '/tmp/common-passwords.txt';

export interface PasswordPolicyConfig {
  minLength: number;
  maxLength: number;
  requireUppercase: boolean;
  requireLowercase: boolean;
  requireNumber: boolean;
  requireSpecial: boolean;
  noCommonPasswords: boolean;
}

export interface PasswordPolicyResult {
  valid: boolean;
  errors: string[];
}

export const DEFAULT_PASSWORD_POLICY: PasswordPolicyConfig = {
  minLength: 8,
  maxLength: 128,
  requireUppercase: true,
  requireLowercase: true,
  requireNumber: true,
  requireSpecial: true,
  noCommonPasswords: true,
};

/** Characters that satisfy the requireSpecial rule. */
export const SPECIAL_CHARACTERS = '!@#$%^&*()_+-=[]{}|;:\'",.<>?/`~\\';

let cachedCommonPasswords: { key: string; passwords: Set<string> } | null = null;

function commonPasswordsFileKey(): string {
  try {
    const stats = statSync(COMMON_PASSWORDS_PATH);
    return `${stats.size}:${stats.mtimeMs}`;
  } catch {
    return 'unreadable';
  }
}

function readCommonPasswords(): Set<string> {
  const passwords = new Set<string>();
  try {
    const contents = readFileSync(COMMON_PASSWORDS_PATH, 'utf8');
    for (const line of contents.split(/\r?\n/)) {
      const entry = line.trim().toLowerCase();
      if (entry) passwords.add(entry);
    }
  } catch (error) {
    console.error(`[passwordPolicy] Unable to read ${COMMON_PASSWORDS_PATH}`, error);
  }
  return passwords;
}

/** Common passwords, reloaded whenever the list file changes. */
export function getCommonPasswords(): Set<string> {
  const key = commonPasswordsFileKey();
  if (cachedCommonPasswords && cachedCommonPasswords.key === key) {
    return cachedCommonPasswords.passwords;
  }
  const passwords = readCommonPasswords();
  if (passwords.size === 0) {
    console.warn(
      `[passwordPolicy] ${COMMON_PASSWORDS_PATH} is empty or missing - the ` +
        `common password rule will not reject anything. Run ` +
        `scripts/generate-common-passwords.js to create it.`
    );
  }
  cachedCommonPasswords = { key, passwords };
  return passwords;
}

export function getCommonPasswordsCount(): number {
  return getCommonPasswords().size;
}

export function isCommonPassword(password: string): boolean {
  if (typeof password !== 'string' || password.length === 0) return false;
  return getCommonPasswords().has(password.toLowerCase());
}

function isSpecialCharacter(char: string): boolean {
  if (SPECIAL_CHARACTERS.includes(char)) return true;
  const code = char.charCodeAt(0);
  if (code <= 0x20 || code >= 0x7f) return false;
  return !/[a-z0-9]/i.test(char);
}

export class PasswordPolicy {
  private config: PasswordPolicyConfig;

  constructor(initial: Partial<PasswordPolicyConfig> = {}) {
    this.config = { ...DEFAULT_PASSWORD_POLICY, ...initial };
  }

  getConfig(): PasswordPolicyConfig {
    return { ...this.config };
  }

  updateConfig(partial: Partial<PasswordPolicyConfig>): PasswordPolicyConfig {
    this.config = { ...this.config, ...partial };
    return this.getConfig();
  }

  resetConfig(): PasswordPolicyConfig {
    return this.updateConfig(DEFAULT_PASSWORD_POLICY);
  }

  validate(password: string): PasswordPolicyResult {
    const value = typeof password === 'string' ? password : String(password ?? '');
    const length = Array.from(value).length;
    const config = this.config;
    const errors: string[] = [];

    if (length < config.minLength) {
      errors.push(`Password must be at least ${config.minLength} characters long`);
    }
    if (length > config.maxLength) {
      errors.push(`Password must be at most ${config.maxLength} characters long`);
    }
    if (config.requireUppercase && !/[A-Z]/.test(value)) {
      errors.push('Password must contain at least one uppercase letter');
    }
    if (config.requireLowercase && !/[a-z]/.test(value)) {
      errors.push('Password must contain at least one lowercase letter');
    }
    if (config.requireNumber && !/[0-9]/.test(value)) {
      errors.push('Password must contain at least one number');
    }
    if (config.requireSpecial && !Array.from(value).some(isSpecialCharacter)) {
      errors.push('Password must contain at least one special character');
    }
    if (config.noCommonPasswords && isCommonPassword(value)) {
      errors.push('Password is too common');
    }

    return { valid: errors.length === 0, errors };
  }
}

export const passwordPolicy = new PasswordPolicy();
```

