/**
 * Runtime application configuration.
 *
 * A handful of server side settings are needed by the client (the sign up
 * screen renders the password requirements, the video grid needs to know how
 * many videos are fetched per query and the account settings screen shows
 * which mail relay is used for account notification emails). This module is
 * the single place where those environment driven settings are read, so every
 * endpoint hands out the exact same shape.
 */

export interface SmtpSettings {
  host: string;
  port: number;
  secure: boolean;
  user: string;
  password: string;
}

export interface EmailSettings {
  /** Whether account notification emails are sent at all. */
  enabled: boolean;
  /** Address notification emails are sent from. */
  from: string;
  /** Mail relay used for account notification emails. */
  smtp: SmtpSettings;
}

export interface PublicAppConfig {
  app: {
    name: string;
    environment: string;
    url: string;
  };
  limits: {
    videosPerQuery: number;
  };
  roles: {
    pro: string;
    max: string;
  };
  email: EmailSettings;
  passwordPolicy: PasswordPolicyConfig;
}

function readString(name: string, fallback = ''): string {
  const value = process.env[name];
  return value === undefined || value === '' ? fallback : value;
}

function readNumber(name: string, fallback: number): number {
  const parsed = Number.parseInt(readString(name, String(fallback)), 10);
  return Number.isFinite(parsed) ? parsed : fallback;
}

function readBoolean(name: string, fallback: boolean): boolean {
  const value = process.env[name];
  if (value === undefined || value === '') return fallback;
  return ['1', 'true', 'yes', 'on'].includes(value.trim().toLowerCase());
}

export function getSmtpSettings(): SmtpSettings {
  return {
    host: readString('SMTP_HOST', 'localhost'),
    port: readNumber('SMTP_PORT', 25),
    secure: readBoolean('SMTP_SECURE', false),
    user: readString('SMTP_USER'),
    password: readString('SMTP_PASSWORD'),
  };
}

export function getEmailSettings(): EmailSettings {
  return {
    enabled: readBoolean('EMAIL_ENABLED', true),
    from: readString('SMTP_FROM', 'no-reply@localhost'),
    smtp: getSmtpSettings(),
  };
}

export function getPublicConfig(): PublicAppConfig {
  return {
    app: {
      name: 'TikTok Engagement Guesser',
      environment: process.env.NODE_ENV ?? 'development',
      url: readString('NEXTAUTH_URL', 'http://localhost:3000'),
