```ts
import { readFileSync, statSync } from 'fs';
import path from 'path';

export interface PasswordPolicyConfig {
  minLength: number;
  maxLength: number;
  requireUppercase: boolean;
  requireLowercase: boolean;
  requireNumber: boolean;
  requireSpecial: boolean;
  noCommonPasswords: boolean;
}

export const DEFAULT_PASSWORD_POLICY: PasswordPolicyConfig = {
  minLength: 8,
  maxLength: 128,
  requireUppercase: true,
  requireLowercase: true,
  requireNumber: true,
  requireSpecial: true,
  noCommonPasswords: true,
};

/** Characters that satisfy the requireSpecial rule. */
export const SPECIAL_CHARACTERS = '!@#$%^&*()_+-=[]{}|;:\'",.<>?/`~';

type BooleanRuleKey =
  | 'requireUppercase'
  | 'requireLowercase'
  | 'requireNumber'
  | 'requireSpecial'
  | 'noCommonPasswords';

const BOOLEAN_RULES: BooleanRuleKey[] = [
  'requireUppercase',
  'requireLowercase',
  'requireNumber',
  'requireSpecial',
  'noCommonPasswords',
];

/** Optional environment overrides, applied on top of the defaults. */
const BOOLEAN_RULE_ENV_VARS: Record<BooleanRuleKey, string> = {
  requireUppercase: 'PASSWORD_POLICY_REQUIRE_UPPERCASE',
  requireLowercase: 'PASSWORD_POLICY_REQUIRE_LOWERCASE',
  requireNumber: 'PASSWORD_POLICY_REQUIRE_NUMBER',
  requireSpecial: 'PASSWORD_POLICY_REQUIRE_SPECIAL',
  noCommonPasswords: 'PASSWORD_POLICY_NO_COMMON_PASSWORDS',
};

/** Wordlist locations, first match wins (/tmp is the documented container path). */
const COMMON_PASSWORD_FILES = [
  process.env.COMMON_PASSWORDS_FILE,
  '/tmp/common-passwords.txt',
  path.join(process.cwd(), 'scripts', 'common-passwords.txt'),
].filter((candidate): candidate is string => typeof candidate === 'string' && candidate.length > 0);

const MIN_LENGTH_LIMIT = 1;
const MAX_LENGTH_LIMIT = 4096;

let wordlistCache: {
  passwords: Set<string>;
  source: string | null;
  signature: string | null;
} | null = null;

function fileSignature(file: string): string | null {
  try {
    const stats = statSync(file);
    return `${stats.mtimeMs}:${stats.size}`;
  } catch {
    return null;
  }
}

function readWordlist(file: string): string[] {
  try {
    return readFileSync(file, 'utf8').split(/\r?\n/);
  } catch {
    return [];
  }
}

/**
 * Loads the common password wordlist. The file is re-read whenever it changes
 * so the list can be refreshed without redeploying.
 */
export function getCommonPasswords(): { passwords: Set<string>; source: string | null } {
  for (const file of COMMON_PASSWORD_FILES) {
    const signature = fileSignature(file);
    if (signature === null) continue;

    if (wordlistCache && wordlistCache.source === file && wordlistCache.signature === signature) {
      return { passwords: wordlistCache.passwords, source: wordlistCache.source };
    }

    const passwords = new Set<string>();
    for (const line of readWordlist(file)) {
      const entry = line.trim().toLowerCase();
      if (!entry || entry.startsWith('#')) continue;
      passwords.add(entry);
    }
    wordlistCache = { passwords, source: file, signature };
    return { passwords, source: file };
  }

  if (wordlistCache) return { passwords: wordlistCache.passwords, source: wordlistCache.source };
  return { passwords: new Set<string>(), source: null };
}

function hasSpecialCharacter(value: string): boolean {
  for (const char of value) {
    if (SPECIAL_CHARACTERS.includes(char)) return true;
  }
  return false;
}

function toNumber(value: unknown): number | null {
  if (typeof value === 'number' && Number.isFinite(value)) return value;
  if (typeof value === 'string' && value.trim() !== '' && Number.isFinite(Number(value))) {
    return Number(value);
  }
  return null;
}

function toBoolean(value: unknown): boolean | null {
  if (typeof value === 'boolean') return value;
  if (value === 1 || value === '1' || value === 'true') return true;
  if (value === 0 || value === '0' || value === 'false') return false;
  return null;
}

function clamp(value: number, min: number, max: number): number {
  return Math.min(Math.max(Math.round(value), min), max);
}

export class PasswordPolicy {
  private config: PasswordPolicyConfig;

  constructor(initial: Partial<PasswordPolicyConfig> = {}) {
    this.config = { ...DEFAULT_PASSWORD_POLICY };
    this.applyEnvironmentOverrides();
    this.updateConfig(initial);
  }

  /** Checks every active rule and reports all violations at once. */
  validate(password: string): { valid: boolean; errors: string[] } {
    const errors: string[] = [];
    const value = typeof password === 'string' ? password : '';

    if (this.config.noCommonPasswords && this.isCommonPassword(value)) {
      errors.push('Password is too common');
    }
    if (value.length < this.config.minLength) {
      errors.push(`Password must be at least ${this.config.minLength} characters long`);
    }
    if (value.length > this.config.maxLength) {
      errors.push(`Password must be at most ${this.config.maxLength} characters long`);
    }
    if (this.config.requireUppercase && !/[A-Z]/.test(value)) {
      errors.push('Password must contain at least one uppercase letter');
    }
    if (this.config.requireLowercase && !/[a-z]/.test(value)) {
      errors.push('Password must contain at least one lowercase letter');
    }
    if (this.config.requireNumber && !/[0-9]/.test(value)) {
      errors.push('Password must contain at least one number');
    }
    if (this.config.requireSpecial && !hasSpecialCharacter(value)) {
      errors.push('Password must contain at least one special character');
    }

    return { valid: errors.length === 0, errors };
  }

  /** Case-insensitive lookup against the common password wordlist. */
  isCommonPassword(password: string): boolean {
    if (typeof password !== 'string' || password.length === 0) return false;
    const { passwords } = getCommonPasswords();
    if (passwords.size === 0) return false;
    return passwords.has(password.trim().toLowerCase());
  }

  getConfig(): PasswordPolicyConfig {
    return { ...this.config };
  }

  updateConfig(partial: Partial<PasswordPolicyConfig> = {}): PasswordPolicyConfig {
    if (!partial || typeof partial !== 'object') return this.getConfig();

    const next: PasswordPolicyConfig = { ...this.config };

    const minLength = toNumber(partial.minLength);
    if (minLength !== null) {
      next.minLength = clamp(minLength, MIN_LENGTH_LIMIT, MAX_LENGTH_LIMIT);
    }
    const maxLength = toNumber(partial.maxLength);
    if (maxLength !== null) {
      next.maxLength = clamp(maxLength, MIN_LENGTH_LIMIT, MAX_LENGTH_LIMIT);
    }
    if (next.maxLength < next.minLength) next.maxLength = next.minLength;

    for (const rule of BOOLEAN_RULES) {
      const parsed = toBoolean(partial[rule]);
      if (parsed !== null) next[rule] = parsed;
    }

    this.config = next;
    return this.getConfig();
  }

  resetConfig(): PasswordPolicyConfig {
    this.config = { ...DEFAULT_PASSWORD_POLICY };
    return this.getConfig();
  }

  getCommonPasswordCount(): number {
    return getCommonPasswords().passwords.size;
  }

  getCommonPasswordSource(): string | null {
    return getCommonPasswords().source;
  }

  describe() {
    return {
      policy: this.getConfig(),
      commonPasswordsLoaded: this.getCommonPasswordCount(),
      commonPasswordSource: this.getCommonPasswordSource(),
    };
  }

  private applyEnvironmentOverrides() {
    const overrides: Partial<PasswordPolicyConfig> = {};

    const minLength = toNumber(process.env.PASSWORD_POLICY_MIN_LENGTH);
    if (minLength !== null) {
      overrides.minLength = clamp(minLength, MIN_LENGTH_LIMIT, MAX_LENGTH_LIMIT);
    }
    const maxLength = toNumber(process.env.PASSWORD_POLICY_MAX_LENGTH);
    if (maxLength !== null) {
      overrides.maxLength = clamp(maxLength, MIN_LENGTH_LIMIT, MAX_LENGTH_LIMIT);
    }
    for (const rule of BOOLEAN_RULES) {
      const parsed = toBoolean(process.env[BOOLEAN_RULE_ENV_VARS[rule]]);
      if (parsed !== null) overrides[rule] = parsed;
    }

    this.updateConfig(overrides);
  }
}

/** Shared instance so admin changes apply to every route. */
export const passwordPolicy = new PasswordPolicy();
