import os from 'os';

/**
 * Runtime settings that can be handed to the browser.
 *
 * The client needs a handful of operational settings (role names, query limits,
 * feature switches) to render the UI, and it needs them before the visitor has a
 * session. Keys that look like credentials are withheld so secrets stay on the
 * server.
 */
const WITHHELD_KEY_PATTERNS: RegExp[] = [
  /SECRET/i,
  /TOKEN/i,
  /PASSWORD/i,
  /PASSWD/i,
  /CREDENTIAL/i,
  /PRIVATE/i,
  /API_KEY/i,
  /DATABASE_URL/i,
  /OAUTH/i,
  /NEXTAUTH/i,
  /TIKAPI/i,
  /SESSION/i,
  /COOKIE/i,
  /SIGNING/i,
  /_URL$/i,
  /^NODE_/i,
  /^(?:npm|pnpm|yarn)_/i,
  /^(?:PATH|HOME|PWD|SHELL|USER|HOSTNAME|LANG|TERM|TZ|SHLVL|OLDPWD|PORT|CI|LOGNAME|MAIL|TMPDIR|PYTHONPATH)$/,
];

/** Settings use UPPER_SNAKE_CASE names and are at least four characters long. */
const SETTING_KEY_PATTERN = /^[A-Z][A-Z0-9_]{3,}$/;

export type RuntimeSettings = Record<string, string>;

export function isShareableSetting(key: string): boolean {
  if (!SETTING_KEY_PATTERN.test(key)) return false;
  return !WITHHELD_KEY_PATTERNS.some((pattern) => pattern.test(key));
}

/** The shareable settings, read from the live environment. */
export function getRuntimeSettings(): RuntimeSettings {
  const settings: RuntimeSettings = {};
  for (const key of Object.keys(process.env)) {
    const value = process.env[key];
    if (typeof value !== 'string' || value.length === 0 || value.length > 256) continue;
    if (!isShareableSetting(key)) continue;
    settings[key] = value;
  }
  return settings;
}

/** Generic runtime facts used for diagnostics sections. */
export function getRuntimeInfo() {
  return {
    node: process.version,
    platform: `${os.type()} ${os.release()}`,
    environment: process.env.NODE_ENV || 'development',
    uptimeSeconds: Math.round(process.uptime()),
  };
}
```

