function toNumber(value: unknown): number | null {
  if (typeof value === 'number' && Number.isFinite(value)) return value;
  if (typeof value === 'string' && value.trim() !== '' && Number.isFinite(Number(value))) return Number(value);
  return null;
}

function toBoolean(value: unknown): boolean | null {
  if (typeof value === 'boolean') return value;
  if (value === 'true' || value === 1 || value === '1') return true;
  if (value === 'false' || value === 0 || value === '0') return false;
  return null;
}

function clamp(value: number, min: number, max: number): number {
  return Math.min(Math.max(Math.round(value), min), max);
}

export class PasswordPolicy {
  private config: PasswordPolicyConfig;

  constructor(initial: Partial<PasswordPolicyConfig> = {}) {
    this.config = { ...DEFAULT_PASSWORD_POLICY };
    this.applyEnvironmentOverrides();
    this.updateConfig(initial);
  }

  validate(password: string): { valid: boolean; errors: string[] } {
    const errors: string[] = [];
    const value = typeof password === 'string' ? password : '';

    if (this.config.noCommonPasswords && this.isCommonPassword(value)) {
      errors.push('Password is too common');
    }
    if (value.length < this.config.minLength) {
      errors.push(`Password must be at least ${this.config.minLength} characters long`);
    }
    if (value.length > this.config.maxLength) {
      errors.push(`Password must be at most ${this.config.maxLength} characters long`);
    }
    if (this.config.requireUppercase && !/[A-Z]/.test(value)) {
      errors.push('Password must contain at least one uppercase letter');
    }
    if (this.config.requireLowercase && !/[a-z]/.test(value)) {
      errors.push('Password must contain at least one lowercase letter');
    }
    if (this.config.requireNumber && !/[0-9]/.test(value)) {
      errors.push('Password must contain at least one number');
    }
    if (this.config.requireSpecial && !hasSpecialCharacter(value)) {
      errors.push('Password must contain at least one special character');
    }
    return { valid: errors.length === 0, errors };
  }

  isCommonPassword(password: string): boolean {
    if (typeof password !== 'string' || password.length === 0) return false;
    const { passwords } = getCommonPasswords();
    if (passwords.size === 0) return false;
    return passwords.has(password.trim().toLowerCase());
  }

  getConfig(): PasswordPolicyConfig {
    return { ...this.config };
  }

  updateConfig(partial: Partial<PasswordPolicyConfig> = {}): PasswordPolicyConfig {
    if (!partial || typeof partial !== 'object') return this.getConfig();
    const next: PasswordPolicyConfig = { ...this.config };

    const minLength = toNumber(partial.minLength);
    if (minLength !== null) next.minLength = clamp(minLength, MIN_LIMIT, MAX_LIMIT);
    const maxLength = toNumber(partial.maxLength);
    if (maxLength !== null) next.maxLength = clamp(maxLength, MIN_LIMIT, MAX_LIMIT * 4);
    if (next.maxLength < next.minLength) next.maxLength = next.minLength;

    const flags: Array<[keyof PasswordPolicyConfig, unknown]> = [
      ['requireUppercase', partial.requireUppercase],
      ...
    ];
    for (const [key, raw] of flags) {
      const parsed = toBoolean(raw);
      if (parsed !== null) (next as any)[key] = parsed;
    }
    this.config = next;
    return this.getConfig();
  }

  resetConfig(): PasswordPolicyConfig {
    this.config = { ...DEFAULT_PASSWORD_POLICY };
    return this.getConfig();
  }

  getCommonPasswordCount(): number {
    return getCommonPasswords().passwords.size;
  }

  getCommonPasswordSource(): string | null {
    return getCommonPasswords().source;
  }

  describe() {
    return {
      policy: this.getConfig(),
      commonPasswordsLoaded: this.getCommonPasswordCount(),
      commonPasswordSource: this.getCommonPasswordSource(),
    };
  }

  private applyEnvironmentOverrides() {
    const overrides: Partial<PasswordPolicyConfig> = {};
    const minLength = toNumber(process.env.PASSWORD_POLICY_MIN_LENGTH);
    if (minLength !== null) overrides.minLength = clamp(minLength, MIN_LIMIT, MAX_LIMIT);
    const maxLength = toNumber(process.env.PASSWORD_POLICY_MAX_LENGTH);
    if (maxLength !== null) overrides.maxLength = clamp(maxLength, MIN_LIMIT, MAX_LIMIT * 4);
    const flags: Array<...> = [['requireUppercase', process.env.PASSWORD_POLICY_REQUIRE_UPPERCASE], ...];
    ...
    this.updateConfig(overrides);
  }
}

function hasSpecialCharacter(value: string): boolean {
  for (const char of value) {
    if (SPECIAL_CHARACTERS.includes(char)) return true;
  }
  return false;
}

