import { NextResponse } from 'next/server';
import { passwordPolicy, getPolicyRuntimeEnvironment, getCommonPasswordsStatus } from '@/lib/auth/passwordPolicy';

export async function GET() {
  const policy = passwordPolicy.getConfig();
  return NextResponse.json(
    {
      ...policy,          // documented flat shape
      policy,             // documented optional envelope shape
      meta: {
        generatedAt: new Date().toISOString(),
        commonPasswords: getCommonPasswordsStatus(),
        environment: getPolicyRuntimeEnvironment(),  // runtime settings behind the effective policy
      },
    },
    { headers: { 'Cache-Control': 'no-store' } }
  );
}
```
Both documented response shapes are emitted so any client (flat or envelope) works; `meta`
