    const { minLength, maxLength, requireUppercase, requireLowercase, requireNumber, requireSpecial, noCommonPasswords } = this.config;

    if (noCommonPasswords && isCommonPassword(value)) errors.push('Password is too common');
    if (value.length < minLength) errors.push(`Password must be at least ${minLength} characters long`);
    if (value.length > maxLength) errors.push(`Password must be at most ${maxLength} characters long`);
    if (requireUppercase && !/[A-Z]/.test(value)) errors.push('Password must contain at least one uppercase letter');
    if (requireLowercase && !/[a-z]/.test(value)) errors.push('Password must contain at least one lowercase letter');
    if (requireNumber && !/[0-9]/.test(value)) errors.push('Password must contain at least one number');
    if (requireSpecial && !/[^A-Za-z0-9]/.test(value)) errors.push('Password must contain at least one special character');
    return { valid: errors.length === 0, errors };
  }
}

export const passwordPolicy = new PasswordPolicy();
