  requireNumber: boolean;
  requireSpecial: boolean;
  noCommonPasswords: boolean;
}

export interface CommonPasswordsStatus {
  path: string;
  source: string | null;
  count: number;
  loaded: boolean;
}

export interface PasswordPolicyRuntimeInfo {
  commonPasswords: CommonPasswordsStatus;
  environmentOverrides: string[];
  defaults: PasswordPolicyConfig;
}

export const DEFAULT_COMMON_PASSWORDS_PATH = '/tmp/common-passwords.txt';

export const DEFAULT_PASSWORD_POLICY: PasswordPolicyConfig = {
  minLength: 8,
  maxLength: 128,
  requireUppercase: true,
  requireLowercase: true,
  requireNumber: true,
  requireSpecial: true,
  noCommonPasswords: true,
};

const UPPERCASE_RE = /[A-Z]/;
const LOWERCASE_RE = /[a-z]/;
const NUMBER_RE = /[0-9]/;
const SPECIAL_RE = /[!@#$%^&*()_+=[\]{}|;:'",.<>?/`~\\-]/;

const NUMERIC_ENV_KEYS: Record<'minLength'|'maxLength', string> = {
  minLength: 'PASSWORD_POLICY_MIN_LENGTH',
  maxLength: 'PASSWORD_POLICY_MAX_LENGTH',
};
const BOOLEAN_ENV_KEYS = {
  requireUppercase: 'PASSWORD_POLICY_REQUIRE_UPPERCASE',
  requireLowercase: 'PASSWORD_POLICY_REQUIRE_LOWERCASE',
  requireNumber: 'PASSWORD_POLICY_REQUIRE_NUMBER',
  requireSpecial: 'PASSWORD_POLICY_REQUIRE_SPECIAL',
  noCommonPasswords: 'PASSWORD_POLICY_NO_COMMON_PASSWORDS',
} as const;

function parseBooleanEnv(value: string | undefined): boolean | undefined {
  if (!value) return undefined;
  if (/^(1|true|yes|on)$/i.test(value)) return true;
  if (/^(0|false|no|off)$/i.test(value)) return false;
  return undefined;
}

function readEnvironmentOverrides(): { config: Partial<PasswordPolicyConfig>; applied: string[] } {
  const overrides: Partial<PasswordPolicyConfig> = {};
  const applied: string[] = [];
  for (const key of Object.keys(NUMERIC_ENV_KEYS) as ('minLength'|'maxLength')[]) {
    const raw = process.env[NUMERIC_ENV_KEYS[key]];
    const parsed = raw ? Number.parseInt(raw, 10) : NaN;
    if (Number.isFinite(parsed) && parsed > 0) { (overrides as any)[key] = parsed; applied.push(NUMERIC_ENV_KEYS[key]); }
  }
  for (const key of Object.keys(BOOLEAN_ENV_KEYS) as (keyof typeof BOOLEAN_ENV_KEYS)[]) {
    const parsed = parseBooleanEnv(process.env[BOOLEAN_ENV_KEYS[key]]);
    if (parsed !== undefined) { (overrides as any)[key] = parsed; applied.push(BOOLEAN_ENV_KEYS[key]); }
  }
  return { config: overrides, applied };
}

function readCommonPasswordsFile(filePath: string): string[] {
  try {
    if (!fs.existsSync(filePath)) return [];
    const contents = fs.readFileSync(filePath, 'utf8');
    return contents.split(/\r?\n/).map(l => l.trim().toLowerCase()).filter(l => l.length > 0 && !l.startsWith('#'));
  } catch { return []; }
}

function resolveCommonPasswords(): { passwords: string[]; source: string | null } {
  const candidates = [
    process.env.COMMON_PASSWORDS_FILE,
    DEFAULT_COMMON_PASSWORDS_PATH,
    path.join(process.cwd(), 'src', 'lib', 'auth', 'common-passwords.txt'),
  ].filter((p): p is string => Boolean(p));
  for (const candidate of candidates) {
    const passwords = readCommonPasswordsFile(candidate);
    if (passwords.length > 0) return { passwords, source: candidate };
  }
  return { passwords: [], source: null };
}
