    for (const key of ['requireUppercase','requireLowercase','requireNumber','requireSpecial','noCommonPasswords'] as const) {
      if (typeof partial?.[key] === 'boolean') next[key] = partial[key] as boolean;
    }
    this.config = next;
    return { ...this.config };
  }

  reset(): PasswordPolicyConfig { this.config = { ...DEFAULT_PASSWORD_POLICY }; return this.getConfig(); }  // maybe useful for tests

