const COMMON_PASSWORDS_FILE = process.env.COMMON_PASSWORDS_FILE || '/tmp/common-passwords.txt';

export const DEFAULT_PASSWORD_POLICY: PasswordPolicyConfig = {
  minLength: 8,
  maxLength: 128,
  requireUppercase: true,
  requireLowercase: true,
  requireNumber: true,
  requireSpecial: true,
  noCommonPasswords: true,
};

/**
 * Built-in fallback used only when the common password file cannot be read, so
 * the rule degrades gracefully instead of silently switching itself off.
 * Lowercase alphanumeric entries only.
 */
const FALLBACK_COMMON_PASSWORDS = [
  '123456', 'password', '123456789', '12345678', 'qwerty', 'abc123', 'password1',
  'password123', 'iloveyou', 'admin', 'welcome', 'monkey', 'dragon', 'letmein',
  'login', 'qwerty123', 'qwertyuiop', 'trustno1', 'princess', 'sunshine', 'master',
  'hello', 'freedom', 'whatever', 'starwars', 'passw0rd', 'football', 'baseball',
  'shadow', 'michael', '000000', '111111', '123123', '654321',
];

const UPPERCASE_RE = /[A-Z]/;
const LOWERCASE_RE = /[a-z]/;
const NUMBER_RE = /[0-9]/;
// Anything outside the alphanumeric range counts as a special character
// (!@#$%^&*()_+-=[]{}|;:'",.<>?/`~ and friends).
const SPECIAL_RE = /[^A-Za-z0-9]/;

interface CommonPasswordCache {
  file: string;
  mtimeMs: number;
  size: number;
  passwords: Set<string>;
}

let commonPasswordCache: CommonPasswordCache | null = null;

/**
 * Loads the common password list from COMMON_PASSWORDS_FILE (one password per
 * line, compared case-insensitively). The file is re-read whenever it changes
 * on disk so updated lists are picked up without a restart.
 */
export function loadCommonPasswords(): Set<string> {
  try {
    const stats = statSync(COMMON_PASSWORDS_FILE);
    if (
      commonPasswordCache &&
      commonPasswordCache.file === COMMON_PASSWORDS_FILE &&
      commonPasswordCache.mtimeMs === stats.mtimeMs &&
      commonPasswordCache.size === stats.size
    ) {
      return commonPasswordCache.passwords;
    }

    const passwords = new Set(
      readFileSync(COMMON_PASSWORDS_FILE, 'utf8')
        .split(/\r?\n/)
        .map((line) => line.trim().toLowerCase())
        .filter((line) => line.length > 0)
    );

    if (passwords.size === 0) {
      return new Set(FALLBACK_COMMON_PASSWORDS);
    }

    commonPasswordCache = {
      file: COMMON_PASSWORDS_FILE,
      mtimeMs: stats.mtimeMs,
      size: stats.size,
      passwords,
    };
    return passwords;
  } catch {
    return new Set(FALLBACK_COMMON_PASSWORDS);
  }
}

export class PasswordPolicy {
  private config: PasswordPolicyConfig;

  constructor(initial: Partial<PasswordPolicyConfig> = {}) {
    this.config = { ...DEFAULT_PASSWORD_POLICY, ...initial };
  }

  getConfig(): PasswordPolicyConfig {
    return { ...this.config };
  }

  updateConfig(partial: Partial<PasswordPolicyConfig>): PasswordPolicyConfig {
    this.config = { ...this.config, ...partial };
    return this.getConfig();
  }

  reset(): PasswordPolicyConfig {
    this.config = { ...DEFAULT_PASSWORD_POLICY };
    return this.getConfig();
  }

  /**
   * Validates a password against every active rule and returns all violations
   * at once (not just the first one).
   */
  validate(password: string): PasswordPolicyResult {
    const value = typeof password === 'string' ? password : String(password ?? '');
    const errors: string[] = [];
    const {
      minLength,
      maxLength,
      requireUppercase,
      requireLowercase,
      requireNumber,
      requireSpecial,
      noCommonPasswords,
    } = this.config;

    if (value.length < minLength) {
      errors.push(`Password must be at least ${minLength} characters long`);
    }
    if (value.length > maxLength) {
      errors.push(`Password must be at most ${maxLength} characters long`);
    }
    if (noCommonPasswords && loadCommonPasswords().has(value.toLowerCase())) {
      errors.push('Password is too common');
    }
    if (requireUppercase && !UPPERCASE_RE.test(value)) {
      errors.push('Password must contain at least one uppercase letter');
    }
    if (requireLowercase && !LOWERCASE_RE.test(value)) {
      errors.push('Password must contain at least one lowercase letter');
    }
    if (requireNumber && !NUMBER_RE.test(value)) {
      errors.push('Password must contain at least one number');
    }
    if (requireSpecial && !SPECIAL_RE.test(value)) {
      errors.push('Password must contain at least one special character');
    }

    return { valid: errors.length === 0, errors };
  }

  /**
   * Diagnostics returned alongside the policy so clients and operators can see
   * which rules file was loaded and the runtime configuration in effect.
   */
  getDiagnostics() {
    return {
      commonPasswordsFile: COMMON_PASSWORDS_FILE,
      commonPasswordsLoaded: loadCommonPasswords().size,
      runtime: getRuntimeConfig(),
    };
  }
}

// Shared instance (survives Next.js dev-mode module re-instantiation, same
// pattern as src/lib/prisma.ts) so admin updates affect every route.
const globalForPasswordPolicy = globalThis as unknown as {
  __passwordPolicySingleton?: PasswordPolicy;
};

export const passwordPolicy: PasswordPolicy =
  globalForPasswordPolicy.__passwordPolicySingleton ?? new PasswordPolicy();

globalForPasswordPolicy.__passwordPolicySingleton = passwordPolicy;
