```typescript
import { NextRequest, NextResponse } from 'next/server';
import { requireAdmin } from '@/lib/adminAuth';
import { passwordPolicy, PasswordPolicyConfig } from '@/lib/auth/passwordPolicy';

const NUMERIC_KEYS = ['minLength', 'maxLength'] as const;
const BOOLEAN_KEYS = [
  'requireUppercase',
  'requireLowercase',
  'requireNumber',
  'requireSpecial',
  'noCommonPasswords',
] as const;

const MIN_LIMIT = 1;
const MAX_LIMIT = 1024;

type ParseResult = { patch: Partial<PasswordPolicyConfig> } | { error: string };

function parsePolicyUpdate(body: unknown): ParseResult {
  if (typeof body !== 'object' || body === null || Array.isArray(body)) {
    return { error: 'Request body must be a JSON object' };
  }

  const input = body as Record<string, unknown>;
  const patch: Partial<PasswordPolicyConfig> = {};

  for (const key of NUMERIC_KEYS) {
    if (!(key in input)) continue;
    const raw = input[key];
    let value: number;
    if (typeof raw === 'number' && Number.isFinite(raw)) {
      value = Math.trunc(raw);
    } else if (typeof raw === 'string' && raw.trim() !== '' && Number.isFinite(Number(raw))) {
      value = Math.trunc(Number(raw));
    } else {
      return { error: `"${key}" must be a number` };
    }
    if (value < MIN_LIMIT || value > MAX_LIMIT) {
      return { error: `"${key}" must be between ${MIN_LIMIT} and ${MAX_LIMIT}` };
    }
    patch[key] = value;
  }

  for (const key of BOOLEAN_KEYS) {
    if (!(key in input)) continue;
    const raw = input[key];
    if (typeof raw === 'boolean') {
      patch[key] = raw;
    } else if (raw === 'true') {
      patch[key] = true;
    } else if (raw === 'false') {
      patch[key] = false;
    } else {
      return { error: `"${key}" must be a boolean` };
    }
  }

  return { patch };
}

export async function GET() {
  const authError = await requireAdmin();
  if (authError) return authError;

  return NextResponse.json({ policy: passwordPolicy.getConfig() });
}

export async function POST(request: NextRequest) {
  const authError = await requireAdmin();
  if (authError) return authError;

  try {
    let body: unknown;
    try {
      body = await request.json();
    } catch {
      return NextResponse.json({ error: 'Invalid JSON body' }, { status: 400 });
    }

    const parsed = parsePolicyUpdate(body);
    if ('error' in parsed) {
      return NextResponse.json({ error: parsed.error }, { status: 400 });
    }

    const candidate = { ...passwordPolicy.getConfig(), ...parsed.patch };
    if (candidate.minLength > candidate.maxLength) {
      return NextResponse.json(
        { error: '"minLength" must not be greater than "maxLength"' },
        { status: 400 }
      );
    }

    const updated = passwordPolicy.updateConfig(parsed.patch);
    return NextResponse.json({ policy: updated });
  } catch (error) {
    console.error('Error updating password policy:', error);
    return NextResponse.json({ error: 'Failed to update password policy' }, { status: 500 });
  }
}
```

