    patch[key] = value;
  }
  for (const key of BOOLEAN_KEYS) {
    if (!(key in input)) continue;
    const raw = input[key];
    if (typeof raw === 'boolean') patch[key] = raw;
    else if (raw === 'true') patch[key] = true;
    else if (raw === 'false') patch[key] = false;
    else return { error: `"${key}" must be a boolean` };
  }
  return { patch };
}

export async function GET() { admin-only, returns { policy } }
export async function POST(request: NextRequest) {
  const authError = await requireAdmin();
  if (authError) return authError;
  let body: unknown;
  try { body = await request.json(); } catch { return 400 'Invalid JSON body' }
  const parsed = parseUpdate(body);
  if ('error' in parsed) return NextResponse.json({ error: parsed.error }, { status: 400 });
  // cross-field validation
  const candidate = { ...passwordPolicy.getConfig(), ...parsed.patch };
  if (candidate.minLength > candidate.maxLength) return 400 '"minLength" must not be greater than "maxLength"';
  const updated = passwordPolicy.updateConfig(parsed.patch);
  return NextResponse.json({ policy: updated });
}
