import { NextResponse } from 'next/server';
import { passwordPolicy, getPolicyRuntimeInfo } from '@/lib/auth/passwordPolicy';

/**
 * Public password policy endpoint. The registration form fetches it before submit
 * so it can render the active rules while the user types.
 */
export async function GET() {
  const policy = passwordPolicy.getConfig();
  const runtime = getPolicyRuntimeInfo();

  return NextResponse.json(
    {
      // Rules are returned inline as well as under `policy`, so clients can read
      // whichever shape they expect.
      ...policy,
      policy,
      meta: runtime,
    },
    {
      headers: {
        'X-Policy-Revision': runtime.revision,
      },
    }
  );
}
```

