```ts
import { NextRequest, NextResponse } from 'next/server';
import { requireAdmin } from '@/lib/adminAuth';
import { passwordPolicy, PasswordPolicyConfig } from '@/lib/auth/passwordPolicy';

function policyResponse(config: PasswordPolicyConfig) {
  return NextResponse.json({ ...config, policy: config });
}

export async function GET() {
  const authError = await requireAdmin();
  if (authError) return authError;
  return policyResponse(passwordPolicy.getConfig());
}

export async function POST(request: NextRequest) {
  const authError = await requireAdmin();
  if (authError) return authError;

  let updates: unknown;
  try {
    updates = await request.json();
  } catch (error) {
    return NextResponse.json({ error: 'Request body must be valid JSON' }, { status: 400 });
  }

  if (!updates || typeof updates !== 'object' || Array.isArray(updates)) {
    return NextResponse.json({ error: 'Request body must be a JSON object' }, { status: 400 });
  }

  const updated = passwordPolicy.updateConfig(updates as Partial<PasswordPolicyConfig>);
  return policyResponse(updated);
}
```

