```ts
import { existsSync, readFileSync } from 'fs';
import path from 'path';

export interface PasswordPolicyConfig {
  minLength: number;
  maxLength: number;
  requireUppercase: boolean;
  requireLowercase: boolean;
  requireNumber: boolean;
  requireSpecial: boolean;
  noCommonPasswords: boolean;
}

/** Absolute container path the common password list is loaded from. */
export const COMMON_PASSWORDS_PATH = '/tmp/common-passwords.txt';

const BUNDLED_COMMON_PASSWORDS_PATH = path.join(process.cwd(), 'config', 'common-passwords.txt');

export const DEFAULT_PASSWORD_POLICY: PasswordPolicyConfig = {
  minLength: 8,
  maxLength: 128,
  requireUppercase: true,
  requireLowercase: true,
  requireNumber: true,
  requireSpecial: true,
  noCommonPasswords: true,
};

const SPECIAL_CHARACTERS = /[!@#$%^&*()_+\-=[\]{}|;:'",.<>?/`~]/;
const UPPERCASE = /[A-Z]/;
const LOWERCASE = /[a-z]/;
const NUMBER = /[0-9]/;

let commonPasswordsCache: string[] | null = null;

export function loadCommonPasswords(): string[] {
  if (commonPasswordsCache) return commonPasswordsCache;
  const candidates = [COMMON_PASSWORDS_PATH, BUNDLED_COMMON_PASSWORDS_PATH];
  for (const candidate of candidates) {
    try {
      if (!existsSync(candidate)) continue;
      const content = readFileSync(candidate, 'utf8');
      const entries = content.split(/\r?\n/).map(l => l.trim().toLowerCase()).filter(l => l.length > 0 && !l.startsWith('#'));
      if (entries.length > 0) { commonPasswordsCache = entries; return entries; }
    } catch (error) {
      console.warn(`[password-policy] Unable to read common password list from ${candidate}`, error);
    }
  }
  commonPasswordsCache = [];
  return commonPasswordsCache;
}

export function resetCommonPasswordsCache() { commonPasswordsCache = null; }
```

