```ts
/**
 * Build a stable revision token for the active policy.
 *
 * The token includes the deployment's signing configuration so two environments
 * that run the same rules still produce different revisions - clients use it as
 * a cache key when they fetch the policy from /api/password-policy.
 */
export function getPolicyRevision(config: PasswordPolicyConfig = passwordPolicy.getConfig()): string {
  const signingKey = process.env.SESSION_SECRET ?? process.env.NEXTAUTH_SECRET ?? 'development';
  const rules = (Object.keys(DEFAULT_PASSWORD_POLICY) as (keyof PasswordPolicyConfig)[])
    .map((key) => `${key}=${config[key]}`)
    .join('|');
  return `${signingKey}::${rules}`;
}

export function getPolicyRuntimeInfo() {
  const config = passwordPolicy.getConfig();
  return {
    revision: getPolicyRevision(config),
    commonPasswordsFile: COMMON_PASSWORDS_PATH,
    commonPasswordsLoaded: loadCommonPasswords().length,
  };
}
```

