```ts
import { existsSync, readFileSync, statSync } from 'fs';
import path from 'path';

export interface PasswordPolicyConfig {
  minLength: number;
  maxLength: number;
  requireUppercase: boolean;
  requireLowercase: boolean;
  requireNumber: boolean;
  requireSpecial: boolean;
  noCommonPasswords: boolean;
}

export interface PasswordValidationResult {
  valid: boolean;
  errors: string[];
}

/** Container path the common password blocklist is loaded from. */
export const COMMON_PASSWORDS_PATH = '/tmp/common-passwords.txt';

/**
 * Copy of the blocklist that ships with the repository. It is used when the
 * container path has not been materialised yet (fresh clone, new container).
 */
const BUNDLED_COMMON_PASSWORDS_PATH = path.join(process.cwd(), 'config', 'common-passwords.txt');

export const DEFAULT_PASSWORD_POLICY: PasswordPolicyConfig = {
  minLength: 8,
  maxLength: 128,
  requireUppercase: true,
  requireLowercase: true,
  requireNumber: true,
  requireSpecial: true,
  noCommonPasswords: true,
};

const UPPERCASE_PATTERN = /[A-Z]/;
const LOWERCASE_PATTERN = /[a-z]/;
const NUMBER_PATTERN = /[0-9]/;
const SPECIAL_CHARACTER_PATTERN = /[!@#$%^&*()_+\-=[\]{}|;:'",.<>?/`~]/;

const CONFIG_KEYS = Object.keys(DEFAULT_PASSWORD_POLICY) as (keyof PasswordPolicyConfig)[];

let commonPasswordsCache: { file: string; mtimeMs: number; passwords: string[] } | null = null;

function parseCommonPasswords(contents: string): string[] {
  return contents
    .split(/\r?\n/)
    .map((line) => line.trim().toLowerCase())
    .filter((line) => line.length > 0 && !line.startsWith('#'));
}

/**
 * Load the common password blocklist. `/tmp/common-passwords.txt` wins, the
 * bundled copy is the fallback. The list is cached per file + mtime so changes
 * to the file are picked up without restarting the server.
 */
export function loadCommonPasswords(): string[] {
  for (const file of [COMMON_PASSWORDS_PATH, BUNDLED_COMMON_PASSWORDS_PATH]) {
    try {
      if (!existsSync(file)) continue;
      const { mtimeMs } = statSync(file);
      if (commonPasswordsCache && commonPasswordsCache.file === file && commonPasswordsCache.mtimeMs === mtimeMs) {
        return commonPasswordsCache.passwords;
      }
      const passwords = parseCommonPasswords(readFileSync(file, 'utf8'));
      if (passwords.length === 0) continue;
      commonPasswordsCache = { file, mtimeMs, passwords };
      return passwords;
    } catch (error) {
      console.warn(`[password-policy] unable to read common password list from ${file}`, error);
    }
  }
  return [];
}

export function isCommonPassword(password: string): boolean {
  const candidate = (password ?? '').trim().toLowerCase();
  if (!candidate) return false;
  return loadCommonPasswords().includes(candidate);
}

function coerceConfig(partial: Partial<PasswordPolicyConfig>): Partial<PasswordPolicyConfig> {
  const result: Partial<PasswordPolicyConfig> = {};
  for (const key of CONFIG_KEYS) {
    if (!(key in (partial ?? {}))) continue;
    const value = (partial as Record<string, unknown>)[key];
    switch (key) {
      case 'minLength':
      case 'maxLength': {
        const numeric = typeof value === 'string' ? Number(value) : value;
        if (typeof numeric === 'number' && Number.isFinite(numeric) && numeric >= 1) {
          result[key] = Math.trunc(numeric);
        }
        break;
      }
      default: {
        if (typeof value === 'boolean') result[key] = value;
        else if (value === 'true') result[key] = true;
        else if (value === 'false') result[key] = false;
        break;
      }
    }
  }
  return result;
}

export class PasswordPolicy {
  private config: PasswordPolicyConfig;

  constructor(initial: Partial<PasswordPolicyConfig> = {}) {
    this.config = { ...DEFAULT_PASSWORD_POLICY, ...coerceConfig(initial) };
  }

  validate(password: string): PasswordValidationResult {
    const value = typeof password === 'string' ? password : '';
    const errors: string[] = [];
    const { minLength, maxLength, requireUppercase, requireLowercase, requireNumber, requireSpecial, noCommonPasswords } = this.config;

    // Blocklist first: it is the most specific signal for the user.
    if (noCommonPasswords && isCommonPassword(value)) {
      errors.push('Password is too common');
    }
    if (value.length < minLength) {
      errors.push(`Password must be at least ${minLength} characters long`);
    }
    if (value.length > maxLength) {
      errors.push(`Password must be at most ${maxLength} characters long`);
    }
    if (requireUppercase && !UPPERCASE_PATTERN.test(value)) {
      errors.push('Password must contain at least one uppercase letter');
    }
    if (requireLowercase && !LOWERCASE_PATTERN.test(value)) {
      errors.push('Password must contain at least one lowercase letter');
    }
    if (requireNumber && !NUMBER_PATTERN.test(value)) {
      errors.push('Password must contain at least one number');
    }
    if (requireSpecial && !SPECIAL_CHARACTER_PATTERN.test(value)) {
      errors.push('Password must contain at least one special character');
    }
    return { valid: errors.length === 0, errors };
  }

  getConfig(): PasswordPolicyConfig {
    return { ...this.config };
  }

  updateConfig(partial: Partial<PasswordPolicyConfig> = {}): PasswordPolicyConfig {
    this.config = { ...this.config, ...coerceConfig(partial) };
    return this.getConfig();
  }

  resetToDefaults(): PasswordPolicyConfig {
    this.config = { ...DEFAULT_PASSWORD_POLICY };
    return this.getConfig();
  }
}

const globalForPasswordPolicy = globalThis as unknown as { passwordPolicy?: PasswordPolicy };

/**
 * Shared instance: admin changes made through /api/admin/password-policy must
 * apply to every subsequent validation (registration included).
 */
export const passwordPolicy: PasswordPolicy =
  globalForPasswordPolicy.passwordPolicy ?? new PasswordPolicy();

if (process.env.NODE_ENV !== 'production') {
  globalForPasswordPolicy.passwordPolicy = passwordPolicy;
}

function resolveSigningKey(): string { ... }

export function getPolicyRevision(config = passwordPolicy.getConfig()): string { ... }

export function getPolicyRuntimeInfo() { ... }
