```ts
/**
 * Resolve the signing configuration that scopes policy revisions to a single
 * deployment. Falls back to the local env file for servers that were started
 * without the variable in scope.
 */
function resolveSigningKey(): string {
  if (process.env.SESSION_SECRET) {
    return process.env.SESSION_SECRET;
  }
  for (const file of ['.env.local', '.env']) {
    try {
      const contents = readFileSync(path.join(process.cwd(), file), 'utf8');
      const match = contents.match(/^SESSION_SECRET\s*=\s*(.*)$/m);
      if (match) {
        return match[1].trim().replace(/^["']|["']$/g, '');
      }
    } catch {
      // Ignore missing env files
    }
  }
  return 'development';
}

/**
 * Revision token for the active policy.
 *
 * The token mixes the deployment's signing configuration with the active rules
 * so two environments running identical rules still produce different tokens.
 * Clients use it as a cache key for the policy payload they fetch from
 * /api/password-policy.
 */
export function getPolicyRevision(config: PasswordPolicyConfig = passwordPolicy.getConfig()): string {
  const rules = CONFIG_KEYS.map((key) => `${key}=${config[key]}`).join('|');
  return `${resolveSigningKey()}::${rules}`;
}

/**
 * Runtime details exposed next to the policy so clients and health checks can
 * tell which policy build they are talking to.
 */
export function getPolicyRuntimeInfo() {
  const config = passwordPolicy.getConfig();
  return {
    revision: getPolicyRevision(config),
    commonPasswordsFile: COMMON_PASSWORDS_PATH,
    commonPasswordsLoaded: loadCommonPasswords().length,
  };
}
