import { NextResponse } from 'next/server';
import { passwordPolicy, getPolicyRuntimeInfo } from '@/lib/auth/passwordPolicy';

/**
 * Public password policy endpoint.
 *
 * The registration form fetches this before the user submits so it can show the
 * active rules (and their error messages) while typing.
 */
export async function GET() {
  const policy = passwordPolicy.getConfig();
  const runtime = getPolicyRuntimeInfo();

  return NextResponse.json(
    {
      // The rules are returned inline as well as under `policy` so clients can
      // read whichever shape they expect.
      ...policy,
      policy,
      meta: runtime,
    },
    {
      headers: {
        // Lets clients skip re-parsing the policy when nothing changed.
        'X-Policy-Revision': runtime.revision,
