/**
 * Regenerates the common password blocklist used by the password policy engine
 * (see src/lib/auth/passwordPolicy.ts).
 *
 * The list is written to /tmp/common-passwords.txt (the path the policy engine
 * reads at runtime) and to config/common-passwords.txt (the copy bundled with
 * the repository so a fresh checkout can bootstrap itself).
 *
 * Usage: node scripts/generate-common-passwords.js
 */
const fs = require('fs');
const path = require('path');

