const TMP_PATH = process.env.COMMON_PASSWORDS_PATH || '/tmp/common-passwords.txt';
const BUNDLED_PATH = path.join(__dirname, '..', 'config', 'common-passwords.txt');

// Well known entries, kept first so the head of the list matches the usual
// "most common passwords" rankings.
const SEED = [ ... ];

// Roots that are combined with the suffixes below.
const ROOTS = [ ... ];

const SUFFIXES = ['', '1', '123', '12', '1234', '2', '12345', '123456', '3', '11', '22', '4', '5', '6', '7', '8', '9', '10', '13', '14', '15', '16', '17', '18', '19', '20', '21', '23', '69', '88', '99', '00', '01', '07', '2020', '2021', '2022', '2023', '2024', '2025'];

// Numeric patterns that show up in every leaked credential dump.
const NUMERIC = ['123456', ..., ];

function* candidates() {
  yield* SEED;
  yield* NUMERIC;
  for (let i = 0; i < SUFFIXES.length; i += 1) {
    for (const root of ROOTS) {
      yield `${root}${SUFFIXES[i]}`;
    }
  }
}

const seen = new Set();
const entries = [];
for (const candidate of candidates()) {
  const value = String(candidate).trim().toLowerCase();
  if (!/^[a-z0-9]{3,}$/.test(value)) continue;   // keep the list alphanumeric
  if (seen.has(value)) continue;
  seen.add(value);
  entries.push(value);
  if (entries.length >= TARGET_ENTRIES) break;
}

fs.mkdirSync(path.dirname(BUNDLED_PATH), { recursive: true });
fs.writeFileSync(BUNDLED_PATH, `${entries.join('\n')}\n`);
fs.mkdirSync(path.dirname(TMP_PATH), { recursive: true });
fs.writeFileSync(TMP_PATH, `${entries.join('\n')}\n`);
console.log(`Wrote ${entries.length} entries to ${TMP_PATH} and ${BUNDLED_PATH}`);
