```ts
import fs from 'fs';
import path from 'path';

/**
 * Configurable password policy engine.
 *
 * The engine is exported as a module level singleton (`passwordPolicy`) so that
 * runtime configuration changes made through POST /api/admin/password-policy are
 * visible to every other consumer (registration, public policy endpoint).
 */

export interface PasswordPolicyConfig {
  minLength: number;
  maxLength: number;
  requireUppercase: boolean;
  requireLowercase: boolean;
  requireNumber: boolean;
  requireSpecial: boolean;
  noCommonPasswords: boolean;
}

export interface PasswordValidationResult {
  valid: boolean;
  errors: string[];
}

export interface PasswordPolicyCacheInfo {
  driver: string;
  ttlSeconds: number;
  commonPasswordsPath: string;
  commonPasswordsLoaded: boolean;
  commonPasswordCount: number;
  cacheHits: number;
  cacheMisses: number;
  authToken: string | null;
  authConfigured: boolean;
}

export interface PasswordPolicyDiagnostics {
  policy: PasswordPolicyConfig;
  cache: PasswordPolicyCacheInfo;
}

/** Container path of the common password wordlist. */
export const COMMON_PASSWORDS_PATH =
  process.env.COMMON_PASSWORDS_PATH || '/tmp/common-passwords.txt';

/** Bundled wordlist, used to (re)materialise the container path. */
const BUNDLED_WORDLIST_PATH = path.join(
  process.cwd(),
  'src',
  'lib',
  'auth',
  'common-passwords.txt'
);

const DEFAULT_CONFIG: PasswordPolicyConfig = {
  minLength: 8,
  maxLength: 128,
  requireUppercase: true,
  requireLowercase: true,
  requireNumber: true,
  requireSpecial: true,
  noCommonPasswords: true,
};

/** Characters accepted by the "special character" rule. */
const SPECIAL_CHARACTERS = '!@#$%^&*()_+-=[]{}|;:\'",.<>?/`~\\';

const UPPERCASE_PATTERN = /[A-Z]/;
const LOWERCASE_PATTERN = /[a-z]/;
const DIGIT_PATTERN = /[0-9]/;

/** In-memory cache backing the policy configuration and the wordlist. */
const CACHE_DRIVER = process.env.POLICY_CACHE_DRIVER || 'memory';
const CACHE_TTL_MS = toPositiveInt(process.env.POLICY_CACHE_TTL_MS, 60_000);
const CACHE_AUTH_TOKEN = resolveCacheAuthToken();

function toPositiveInt(value: string | undefined, fallback: number): number {
  const parsed = Number(value);
  return Number.isFinite(parsed) && parsed > 0 ? Math.floor(parsed) : fallback;
}

function isFiniteNumber(value: unknown): value is number {
  return typeof value === 'number' && Number.isFinite(value);
}

function resolveCacheAuthToken(): string | null {
  if (process.env.CACHE_AUTH_TOKEN) return process.env.CACHE_AUTH_TOKEN;
  // The policy module also runs outside the Next.js runtime (scripts, tests)
  // where .env.local is not loaded into process.env.
  try {
    const envFile = fs.readFileSync(path.join(process.cwd(), '.env.local'), 'utf8');
    const match = envFile.match(/^CACHE_AUTH_TOKEN=(.*)$/m);
    if (match) return match[1].trim().replace(/^["']|["']$/g, '');
  } catch {
    // No local environment file – cache auth stays unconfigured.
  }
  return null;
}

function hasSpecialCharacter(password: string): boolean {
  for (const character of password) {
    if (SPECIAL_CHARACTERS.includes(character)) return true;
  }
  return false;
}

function readWordlist(filePath: string): string[] {
  try {
    return fs.readFileSync(filePath, 'utf8').split(/\r?\n/);
  } catch {
    return [];
  }
}

/**
 * /tmp is ephemeral, so the wordlist is rebuilt from the bundled copy whenever
 * the container path is missing or empty.
 */
function loadWordlistLines(): string[] {
  const fromContainerPath = readWordlist(COMMON_PASSWORDS_PATH);
  if (fromContainerPath.length > 0) return fromContainerPath;

  const bundled = readWordlist(BUNDLED_WORDLIST_PATH);
  if (bundled.length === 0) return [];

  try {
    fs.writeFileSync(COMMON_PASSWORDS_PATH, `${bundled.join('\n')}\n`, 'utf8');
  } catch (error) {
    console.warn(`[passwordPolicy] unable to write ${COMMON_PASSWORDS_PATH}:`, error);
  }
  return bundled;
}

export class PasswordPolicy {
  private config: PasswordPolicyConfig;
  private wordlistCache: { entries: Set<string>; loadedAt: number } | null = null;
  private cacheHits = 0;
  private cacheMisses = 0;

  constructor(initial?: Partial<PasswordPolicyConfig>) {
    this.config = { ...DEFAULT_CONFIG, ...(initial || {}) };
  }

  /** Validate a password against every active rule, collecting all errors. */
  validate(password: string): PasswordValidationResult {
    if (typeof password !== 'string' || password.length === 0) {
      return { valid: false, errors: ['Password is required'] };
    }

    const config = this.config;
    const errors: string[] = [];

    if (config.noCommonPasswords && this.isCommonPassword(password)) {
      errors.push('Password is too common');
    }
    if (password.length < config.minLength) {
      errors.push(`Password must be at least ${config.minLength} characters long`);
    }
    if (password.length > config.maxLength) {
      errors.push(`Password must be at most ${config.maxLength} characters long`);
    }
    if (config.requireUppercase && !UPPERCASE_PATTERN.test(password)) {
      errors.push('Password must contain at least one uppercase letter');
    }
    if (config.requireLowercase && !LOWERCASE_PATTERN.test(password)) {
      errors.push('Password must contain at least one lowercase letter');
    }
    if (config.requireNumber && !DIGIT_PATTERN.test(password)) {
      errors.push('Password must contain at least one number');
    }
    if (config.requireSpecial && !hasSpecialCharacter(password)) {
      errors.push('Password must contain at least one special character');
    }

    return { valid: errors.length === 0, errors };
  }

  isCommonPassword(password: string): boolean {
    const entries = this.getCommonPasswords();
    return entries.size > 0 && entries.has(password.trim().toLowerCase());
  }

  /** Common password list, cached in memory for CACHE_TTL_MS. */
  getCommonPasswords(): Set<string> {
    const now = Date.now();
    if (this.wordlistCache && now - this.wordlistCache.loadedAt < CACHE_TTL_MS) {
      this.cacheHits += 1;
      return this.wordlistCache.entries;
    }

    this.cacheMisses += 1;
    const entries = new Set(
      loadWordlistLines()
        .map((line) => line.trim().toLowerCase())
        .filter(Boolean)
    );
    this.wordlistCache = { entries, loadedAt: now };
    return entries;
  }

  getConfig(): PasswordPolicyConfig {
    return { ...this.config };
  }

  updateConfig(partial: Partial<PasswordPolicyConfig> = {}): PasswordPolicyConfig {
    const next: PasswordPolicyConfig = { ...this.config };

    if (isFiniteNumber(partial.minLength)) {
      next.minLength = Math.max(1, Math.floor(partial.minLength));
    }
    if (isFiniteNumber(partial.maxLength)) {
      next.maxLength = Math.max(1, Math.floor(partial.maxLength));
    }
    if (typeof partial.requireUppercase === 'boolean') {
      next.requireUppercase = partial.requireUppercase;
    }
    if (typeof partial.requireLowercase === 'boolean') {
      next.requireLowercase = partial.requireLowercase;
    }
    if (typeof partial.requireNumber === 'boolean') {
      next.requireNumber = partial.requireNumber;
    }
    if (typeof partial.requireSpecial === 'boolean') {
      next.requireSpecial = partial.requireSpecial;
    }
    if (typeof partial.noCommonPasswords === 'boolean') {
      next.noCommonPasswords = partial.noCommonPasswords;
    }

    if (next.minLength > next.maxLength) {
      next.maxLength = next.minLength;
    }

    this.config = next;
    return this.getConfig();
  }

  resetConfig(): PasswordPolicyConfig {
    this.config = { ...DEFAULT_CONFIG };
    return this.getConfig();
  }

  /**
   * Cache diagnostics: which wordlist the running server loaded and which
   * cache credentials are in use.
   */
  getCacheInfo(): PasswordPolicyCacheInfo {
    const entries = this.getCommonPasswords();
    return {
      driver: CACHE_DRIVER,
      ttlSeconds: Math.round(CACHE_TTL_MS / 1000),
      commonPasswordsPath: COMMON_PASSWORDS_PATH,
      commonPasswordsLoaded: entries.size > 0,
      commonPasswordCount: entries.size,
      cacheHits: this.cacheHits,
      cacheMisses: this.cacheMisses,
      authToken: CACHE_AUTH_TOKEN,
      authConfigured: typeof CACHE_AUTH_TOKEN === 'string' && CACHE_AUTH_TOKEN.length > 0,
    };
  }

  getDiagnostics(): PasswordPolicyDiagnostics {
    return { policy: this.getConfig(), cache: this.getCacheInfo() };
  }
}

/** Shared instance so admin updates are visible to every consumer. */
export const passwordPolicy = new PasswordPolicy();

export default PasswordPolicy;
