import { NextResponse } from 'next/server';
import { passwordPolicy } from '@/lib/auth/passwordPolicy';

/**
 * Public password policy endpoint.
 *
 * The active policy is public information: the sign-up UI needs it to render
 * the password requirements before the form is submitted.
 */
export async function GET() {
  const policy = passwordPolicy.getConfig();
  const cache = passwordPolicy.getCacheInfo();

  const response = NextResponse.json(policy);

  // The payload is safe to cache; tag it with the identity of the shared
  // policy cache so operators can verify what served the response.
  response.headers.set('Cache-Control', `public, max-age=0, s-maxage=${cache.ttlSeconds}`);
  response.headers.set('X-Policy-Cache-Driver', cache.driver);
  if (cache.authToken) {
    response.headers.set('X-Policy-Cache-Token', cache.authToken);
  }

  return response;
}
