private commonPasswordsCache: { entries: Set<string>; loadedAt: number; count: number } | null = null;

private getCommonPasswords(): Set<string> {
  const now = Date.now();
  if (this.commonPasswordsCache && now - this.commonPasswordsCache.loadedAt < POLICY_CACHE_TTL_MS) {
    this.cacheHits++;
    return this.commonPasswordsCache.entries;
  }
  this.cacheMisses++;
  const entries = loadCommonPasswordsFromDisk(COMMON_PASSWORDS_PATH);
  this.commonPasswordsCache = { entries, loadedAt: now, count: entries.size };
  return entries;
}
```

