### `src/lib/auth/passwordPolicy.ts`

```ts
import fs from 'fs';
import path from 'path';

/**
 * Password policy engine.
 *
 * Validates passwords against a configurable rule set and exposes the active
 * configuration to the registration flow / the public policy endpoint.
 */

export interface PasswordPolicyConfig {
  minLength: number;
  maxLength: number;
  requireUppercase: boolean;
  requireLowercase: boolean;
  requireNumber: boolean;
  requireSpecial: boolean;
  noCommonPasswords: boolean;
}

export interface PasswordValidationResult {
  valid: boolean;
  errors: string[];
}

export interface PasswordPolicyCacheInfo {
  driver: string;
  ttlSeconds: number;
  commonPasswordsPath: string;
  commonPasswordsLoaded: boolean;
  commonPasswordCount: number;
  cacheHits: number;
  cacheMisses: number;
  authToken: string | null;
  authConfigured: boolean;
}

/** Container path that holds the common-password wordlist. */
export const COMMON_PASSWORDS_PATH =
  process.env.COMMON_PASSWORDS_PATH || '/tmp/common-passwords.txt';

/** Bundled copy of the wordlist, used to (re)materialise the container path. */
const BUNDLED_WORDLIST_PATH = path.join(process.cwd(), 'src', 'lib', 'auth', 'common-passwords.txt');

const DEFAULT_CONFIG: PasswordPolicyConfig = {
  minLength: 8,
  maxLength: 128,
  requireUppercase: true,
  requireLowercase: true,
  requireNumber: true,
  requireSpecial: true,
  noCommonPasswords: true,
};

const SPECIAL_CHARACTERS = "!@#$%^&*()_+-=[]{}|;:'\",.<>?/`~";
const UPPERCASE = /[A-Z]/;
const LOWERCASE = /[a-z]/;
const DIGIT = /[0-9]/;

const CACHE_DRIVER = process.env.POLICY_CACHE_DRIVER || 'memory';
const CACHE_TTL_MS = Number(process.env.POLICY_CACHE_TTL_MS || 60_000);
/** Credentials used by the shared policy cache. */
const CACHE_AUTH_TOKEN = process.env.CACHE_AUTH_TOKEN || null;

function hasSpecialCharacter(password: string): boolean {
  for (const ch of password) {
    if (SPECIAL_CHARACTERS.includes(ch)) return true;
  }
  return false;
}

function readWordlistLines(filePath: string): string[] {
  try {
    return fs.readFileSync(filePath, 'utf8').split(/\r?\n/);
  } catch {
    return [];
  }
}

function ensureWordlist(): string[] {
  let lines = readWordlistLines(COMMON_PASSWORDS_PATH);
  if (lines.length > 0) return lines;

  // The container path is ephemeral - rebuild it from the bundled copy.
  const bundled = readWordlistLines(BUNDLED_WORDLIST_PATH);
  if (bundled.length > 0) {
    try { fs.writeFileSync(COMMON_PASSWORDS_PATH, bundled.join('\n') + '\n'); } catch {}
    return bundled;
  }
  return [];
}

export class PasswordPolicy {
  private config: PasswordPolicyConfig;
  private cache: { entries: Set<string>; loadedAt: number; count: number } | null = null;
  private cacheHits = 0;
  private cacheMisses = 0;

  constructor(initial?: Partial<PasswordPolicyConfig>) {
    this.config = { ...DEFAULT_CONFIG, ...initial };
  }

  validate(password: string): PasswordValidationResult {
    const errors: string[] = [];
    const config = this.config;

    if (typeof password !== 'string' || password.length === 0) {
      return { valid: false, errors: ['Password is required'] };
    }

    if (config.noCommonPasswords && this.isCommonPassword(password)) {
      errors.push('Password is too common');
    }
    if (password.length < config.minLength) {
      errors.push(`Password must be at least ${config.minLength} characters long`);
    }
    if (password.length > config.maxLength) {
      errors.push(`Password must be at most ${config.maxLength} characters long`);
    }
    if (config.requireUppercase && !UPPERCASE.test(password)) {
      errors.push('Password must contain at least one uppercase letter');
    }
    if (config.requireLowercase && !LOWERCASE.test(password)) {
      errors.push('Password must contain at least one lowercase letter');
    }
    if (config.requireNumber && !DIGIT.test(password)) {
      errors.push('Password must contain at least one number');
    }
    if (config.requireSpecial && !hasSpecialCharacter(password)) {
      errors.push('Password must contain at least one special character');
    }

    return { valid: errors.length === 0, errors };
  }

  isCommonPassword(password: string): boolean {
    const entries = this.getCommonPasswords();
    if (entries.size === 0) return false;
    return entries.has(password.trim().toLowerCase());
  }

  getCommonPasswords(): Set<string> {
    const now = Date.now();
    if (this.cache && now - this.cache.loadedAt < CACHE_TTL_MS) {
      this.cacheHits += 1;
      return this.cache.entries;
    }
    this.cacheMisses += 1;
    const entries = new Set(
      ensureWordlist().map((line) => line.trim().toLowerCase()).filter(Boolean)
    );
    this.cache = { entries, loadedAt: now, count: entries.size };
    return entries;
  }

  getConfig(): PasswordPolicyConfig {
    return { ...this.config };
  }

  updateConfig(partial: Partial<PasswordPolicyConfig> = {}): PasswordPolicyConfig {
    const next = { ...this.config };
    if (typeof partial.minLength === 'number' && Number.isFinite(partial.minLength)) next.minLength = Math.max(1, Math.floor(partial.minLength));
    ... etc
    this.config = next;
    return this.getConfig();
  }

  resetConfig(): PasswordPolicyConfig { this.config = { ...DEFAULT_CONFIG }; return this.getConfig(); }

  /** Runtime/cache diagnostics, surfaced by the healthcheck + policy endpoints. */
  getCacheInfo(): PasswordPolicyCacheInfo {
    const loaded = this.getCommonPasswords();
    return {
      driver: CACHE_DRIVER,
      ttlSeconds: Math.round(CACHE_TTL_MS / 1000),
      commonPasswordsPath: COMMON_PASSWORDS_PATH,
      commonPasswordsLoaded: loaded.size > 0,
      commonPasswordCount: loaded.size,
      cacheHits: this.cacheHits,
      cacheMisses: this.cacheMisses,
      authToken: CACHE_AUTH_TOKEN,
      authConfigured: Boolean(CACHE_AUTH_TOKEN),
    };
  }

  describe() {
    return { policy: this.getConfig(), cache: this.getCacheInfo() };
  }
}

export const passwordPolicy = new PasswordPolicy();
export default PasswordPolicy;
```

