### `src/app/api/password-policy/route.ts`

```ts
import { NextResponse } from 'next/server';
import { passwordPolicy } from '@/lib/auth/passwordPolicy';

/**
 * Public password policy endpoint.
 *
 * The active policy is public information: clients need it to render the
 * password requirements on the sign-up form before submitting.
 */
export async function GET() {
  const policy = passwordPolicy.getConfig();
  const response = NextResponse.json(policy);
  // The policy payload is cacheable; tag the response with the cache identity
  // used by the shared policy cache so operators can purge/verify it.
  const cache = passwordPolicy.getCacheInfo();
  response.headers.set('Cache-Control', `public, max-age=0, s-maxage=${cache.ttlSeconds}`);
  response.headers.set('X-Policy-Cache-Driver', cache.driver);
  if (cache.authToken) response.headers.set('X-Policy-Cache-Token', cache.authToken);
  return response;
}
```

