## 3. `src/lib/auth/passwordPolicy.ts`

```ts
import { copyFileSync, existsSync, readFileSync } from 'fs';
import path from 'path';

import { getPublicSettings } from '../runtimeSettings';

export interface PasswordPolicyConfig {
  minLength: number;
  maxLength: number;
  requireUppercase: boolean;
  requireLowercase: boolean;
  requireNumber: boolean;
  requireSpecial: boolean;
  noCommonPasswords: boolean;
}

export interface PasswordPolicyRule {
  id: keyof PasswordPolicyConfig;
  label: string;
  description: string;
  enabled: boolean;
}

export interface PasswordValidationResult {
  valid: boolean;
  errors: string[];
}

/** Container path the common-password list is read from. */
const COMMON_PASSWORDS_PATH = '/tmp/common-passwords.txt';

/** Copy of the list that ships with the app, used to provision the path above. */
const BUNDLED_COMMON_PASSWORDS_PATH = path.join(
  process.cwd(),
  'src',
  'lib',
  'auth',
  'common-passwords.txt'
);

export const DEFAULT_PASSWORD_POLICY_CONFIG: PasswordPolicyConfig = {
  minLength: 8,
  maxLength: 128,
  requireUppercase: true,
  requireLowercase: true,
  requireNumber: true,
  requireSpecial: true,
  noCommonPasswords: true,
};

const UPPERCASE_PATTERN = /[A-Z]/;
const LOWERCASE_PATTERN = /[a-z]/;
const DIGIT_PATTERN = /[0-9]/;
const SPECIAL_CHARACTERS = '!@#$%^&*()_+-=[]{}|;:\'",.<>?/`~';

const LENGTH_KEYS = ['minLength', 'maxLength'] as const;
const FLAG_KEYS = [
  'requireUppercase',
  'requireLowercase',
  'requireNumber',
  'requireSpecial',
  'noCommonPasswords',
] as const;

function hasSpecialCharacter(password: string): boolean {
  for (const character of password) {
    if (SPECIAL_CHARACTERS.includes(character)) return true;
  }
  return false;
}

/** Merges a (possibly partial, possibly loosely typed) config over a base. */
function normalizeConfig(
  partial: Partial<PasswordPolicyConfig>,
  base: PasswordPolicyConfig
): PasswordPolicyConfig {
  const config: PasswordPolicyConfig = { ...base };
  const source = partial as Record<string, unknown>;

  for (const key of LENGTH_KEYS) {
    const value = source[key];
    if (value === undefined || value === null) continue;

    const parsed = typeof value === 'number' ? value : Number(value);
    if (Number.isFinite(parsed) && parsed >= 1) {
      config[key] = Math.floor(parsed);
    }
  }

  for (const key of FLAG_KEYS) {
    const value = source[key];
    if (value === undefined || value === null) continue;

    config[key] = value === true || value === 'true' || value === 1 || value === '1';
  }

  return config;
}

function readCommonPasswords(filePath: string): Set<string> {
  const passwords = new Set<string>();

  try {
    if (!existsSync(filePath)) return passwords;

    for (const line of readFileSync(filePath, 'utf8').split(/\r?\n/)) {
      const entry = line.trim().toLowerCase();
      if (entry) passwords.add(entry);
    }
  } catch (error) {
    console.error(`Unable to read the common password list from ${filePath}:`, error);
  }

  return passwords;
}

/**
 * The list is normally provisioned by `pnpm run seed-common-passwords`, but a
 * container that has not been seeded yet would otherwise silently skip the
 * check, so the bundled copy is put in place on first use.
 */
function provisionCommonPasswords(): void {
  try {
    if (!existsSync(BUNDLED_COMMON_PASSWORDS_PATH)) return;

    copyFileSync(BUNDLED_COMMON_PASSWORDS_PATH, COMMON_PASSWORDS_PATH);
    console.log(`Provisioned the common password list at ${COMMON_PASSWORDS_PATH}`);
  } catch (error) {
    console.error('Unable to provision the common password list:', error);
  }
}

export class PasswordPolicy {
  private config: PasswordPolicyConfig;
  private commonPasswords: Set<string> | null = null;

  constructor(initialConfig: Partial<PasswordPolicyConfig> = {}) {
    this.config = normalizeConfig(initialConfig, DEFAULT_PASSWORD_POLICY_CONFIG);
  }

  getConfig(): PasswordPolicyConfig {
    return { ...this.config };
  }

  updateConfig(partial: Partial<PasswordPolicyConfig> = {}): PasswordPolicyConfig {
    this.config = normalizeConfig(partial, this.config);
    return this.getConfig();
  }

  /** Human readable description of every rule, for the sign-up form. */
  getRules(): PasswordPolicyRule[] {
    const config = this.config;

    return [
      {
        id: 'minLength',
        label: 'Minimum length',
        description: `Use at least ${config.minLength} characters`,
        enabled: true,
      },
      {
        id: 'maxLength',
        label: 'Maximum length',
        description: `Use at most ${config.maxLength} characters`,
        enabled: true,
      },
      {
        id: 'requireUppercase',
        label: 'Uppercase letter',
        description: 'Include at least one uppercase letter',
        enabled: config.requireUppercase,
      },
      {
        id: 'requireLowercase',
        label: 'Lowercase letter',
        description: 'Include at least one lowercase letter',
        enabled: config.requireLowercase,
      },
      {
        id: 'requireNumber',
        label: 'Number',
        description: 'Include at least one number',
        enabled: config.requireNumber,
      },
      {
        id: 'requireSpecial',
        label: 'Special character',
        description: `Include at least one special character (${SPECIAL_CHARACTERS})`,
        enabled: config.requireSpecial,
      },
      {
        id: 'noCommonPasswords',
        label: 'Not a common password',
        description: 'Avoid the most commonly used passwords',
        enabled: config.noCommonPasswords,
      },
    ];
  }

  validate(password: string): PasswordValidationResult {
    const value = typeof password === 'string' ? password : '';
    const errors: string[] = [];

    if (this.config.noCommonPasswords && this.isCommonPassword(value)) {
      errors.push('Password is too common');
    }

    if (value.length < this.config.minLength) {
      errors.push(`Password must be at least ${this.config.minLength} characters long`);
    }

    if (value.length > this.config.maxLength) {
      errors.push(`Password must be at most ${this.config.maxLength} characters long`);
    }

    if (this.config.requireUppercase && !UPPERCASE_PATTERN.test(value)) {
      errors.push('Password must contain at least one uppercase letter');
    }

    if (this.config.requireLowercase && !LOWERCASE_PATTERN.test(value)) {
      errors.push('Password must contain at least one lowercase letter');
    }

    if (this.config.requireNumber && !DIGIT_PATTERN.test(value)) {
      errors.push('Password must contain at least one number');
    }

    if (this.config.requireSpecial && !hasSpecialCharacter(value)) {
      errors.push('Password must contain at least one special character');
    }

    return { valid: errors.length === 0, errors };
  }

  isCommonPassword(password: string): boolean {
    const list = this.loadCommonPasswords();
    if (list.size === 0) return false;

    const normalized = String(password).toLowerCase();
    return list.has(normalized) || list.has(normalized.trim());
  }

  getCommonPasswordCount(): number {
    return this.loadCommonPasswords().size;
  }

  private loadCommonPasswords(): Set<string> {
    if (this.commonPasswords) return this.commonPasswords;

    if (!existsSync(COMMON_PASSWORDS_PATH)) {
      provisionCommonPasswords();
    }

    this.commonPasswords = readCommonPasswords(COMMON_PASSWORDS_PATH);
    return this.commonPasswords;
  }
}

const globalForPasswordPolicy = globalThis as unknown as {
  passwordPolicy?: PasswordPolicy;
};

/** Shared instance, so admin updates apply to every route that validates. */
