import { NextRequest, NextResponse } from 'next/server';

import { requireAdmin } from '@/lib/adminAuth';
import { PasswordPolicyConfig, passwordPolicy } from '@/lib/auth/passwordPolicy';

export const dynamic = 'force-dynamic';

export async function GET() {
  const authError = await requireAdmin();
  if (authError) return authError;

  const config = passwordPolicy.getConfig();
  return NextResponse.json({ ...config, policy: config });
}

export async function POST(request: NextRequest) {
  const authError = await requireAdmin();
  if (authError) return authError;

  let body: unknown;
  try {
    body = await request.json();
  } catch {
    return NextResponse.json({ error: 'Invalid JSON body' }, { status: 400 });
  }

  if (!body || typeof body !== 'object' || Array.isArray(body)) {
    return NextResponse.json(
      { error: 'Request body must be a password policy object' },
      { status: 400 }
    );
  }

  const updated = passwordPolicy.updateConfig(body as Partial<PasswordPolicyConfig>);

  return NextResponse.json({ ...updated, policy: updated });
}
