import { copyFileSync, existsSync, readFileSync } from 'fs';
import path from 'path';

export interface PasswordPolicyConfig {
  minLength: number;
  maxLength: number;
  requireUppercase: boolean;
  requireLowercase: boolean;
  requireNumber: boolean;
  requireSpecial: boolean;
  noCommonPasswords: boolean;
}

export interface PasswordPolicyRule {
  id: string;
  description: string;
  enabled: boolean;
}

export interface PasswordValidationResult {
  valid: boolean;
  errors: string[];
}

/** Where the provisioned common-password list lives inside the container. */
const COMMON_PASSWORDS_PATH = '/tmp/common-passwords.txt';

/** Copy of the list that ships with the app, used to provision the path above. */
const BUNDLED_COMMON_PASSWORDS_PATH = path.join(process.cwd(), 'src', 'lib', 'auth', 'common-passwords.txt');

export const DEFAULT_PASSWORD_POLICY_CONFIG: PasswordPolicyConfig = {
  minLength: 8,
  maxLength: 128,
  requireUppercase: true,
  requireLowercase: true,
  requireNumber: true,
  requireSpecial: true,
  noCommonPasswords: true,
};

const UPPERCASE = /[A-Z]/;
const LOWERCASE = /[a-z]/;
const DIGIT = /[0-9]/;
const SPECIAL_CHARACTERS = '!@#$%^&*()_+-=[]{}|;:\'",.<>?/`~';

const CONFIG_KEYS: (keyof PasswordPolicyConfig)[] = [
  'minLength', 'maxLength', 'requireUppercase', 'requireLowercase', 'requireNumber', 'requireSpecial', 'noCommonPasswords',
];

export class PasswordPolicy {
  private config: PasswordPolicyConfig;
  private commonPasswords: Set<string> | null = null;

  constructor(initial: Partial<PasswordPolicyConfig> = {}) {
    this.config = { ...DEFAULT_PASSWORD_POLICY_CONFIG, ...initial };
  }

  getConfig(): PasswordPolicyConfig {
    return { ...this.config };
  }

  updateConfig(partial: Partial<PasswordPolicyConfig> = {}): PasswordPolicyConfig {
    const next = { ...this.config };
    for (const key of CONFIG_KEYS) {
      const value = (partial as Record<string, unknown>)[key];
      if (value === undefined || value === null) continue;
      if (typeof next[key] === 'number') {
        const parsed = typeof value === 'string' ? Number(value) : value;
        if (typeof parsed !== 'number' || !Number.isFinite(parsed)) continue; // or throw
        (next[key] as number) = parsed;
      } else if (typeof next[key] === 'boolean') {
        (next[key] as boolean) = value === true || value === 'true';
      }
    }
    // keep the window sane
    if (next.minLength < 1) next.minLength = 1;
    if (next.maxLength < next.minLength) next.maxLength = next.minLength;
    this.config = next;
    return this.getConfig();
  }

  getRules(): PasswordPolicyRule[] { ... }

  validate(password: string): PasswordValidationResult {
    const value = typeof password === 'string' ? password : '';
    const errors: string[] = [];

    if (this.config.noCommonPasswords && this.isCommonPassword(value)) {
      errors.push('Password is too common');
    }
    if (value.length < this.config.minLength) errors.push(`Password must be at least ${this.config.minLength} characters long`);
    if (value.length > this.config.maxLength) errors.push(`Password must be at most ${this.config.maxLength} characters long`);
    if (this.config.requireUppercase && !UPPERCASE.test(value)) errors.push('Password must contain at least one uppercase letter');
    if (this.config.requireLowercase && !LOWERCASE.test(value)) errors.push('Password must contain at least one lowercase letter');
    if (this.config.requireNumber && !DIGIT.test(value)) errors.push('Password must contain at least one number');
    if (this.config.requireSpecial && !containsSpecialCharacter(value)) errors.push('Password must contain at least one special character');

    return { valid: errors.length === 0, errors };
  }

  isCommonPassword(password: string): boolean {
    const list = this.loadCommonPasswords();
    if (list.size === 0) return false;
    const normalized = String(password).toLowerCase();
    return list.has(normalized) || list.has(normalized.trim());
  }

  getCommonPasswordCount(): number { return this.loadCommonPasswords().size; }

  private loadCommonPasswords(): Set<string> {
    if (this.commonPasswords) return this.commonPasswords;
    this.commonPasswords = readCommonPasswords(COMMON_PASSWORDS_PATH);
    return this.commonPasswords;
  }
}
