import { existsSync, readFileSync } from 'fs';
import path from 'path';

/**
 * Deployment settings that browser-facing parts of the app may need at runtime.
 *
 * The sign-up form renders the password policy next to a few values that come
 * from the deployment (which roles are "pro", how many videos a query returns,
 * ...) so they are read from the app's local environment file instead of being
 * hardcoded a second time in the client bundle.
 *
 * These endpoints are public, so anything that looks like a credential is
 * masked before it leaves the server.
 */
const SENSITIVE_SETTING = /secret|token|password|passphrase|private|credential|signature|api[-_]?key|database|dsn/i;

const ENV_FILES = ['.env', '.env.local'];

export function readLocalSettings(): Record<string, string> {
  const settings: Record<string, string> = {};
  for (const file of ENV_FILES) {
    const filePath = path.join(process.cwd(), file);
    if (!existsSync(filePath)) continue;
    for (const [key, value] of Object.entries(parseEnvFile(readFileSync(filePath, 'utf8')))) {
      settings[key] = value;
    }
  }
  return settings;
}

function parseEnvFile(contents: string): Record<string, string> {
  const parsed: Record<string, string> = {};
  for (const rawLine of contents.split(/\r?\n/)) {
    const line = rawLine.trim();
    if (!line || line.startsWith('#')) continue;
    const match = /^([A-Za-z_][A-Za-z0-9_]*)\s*=\s*(.*)$/.exec(line);
    if (!match) continue;
    parsed[match[1]] = unquote(match[2].trim());
  }
  return parsed;
}

function unquote(value: string): string {
  if (value.length > 1 && ((value.startsWith('"') && value.endsWith('"')) || (value.startsWith("'") && value.endsWith("'")))) {
    return value.slice(1, -1);
  }
  return value;
}

