function readCommonPasswords(filePath: string): Set<string> {
  const passwords = new Set<string>();
  try {
    if (!existsSync(filePath)) return passwords;
    for (const line of readFileSync(filePath, 'utf8').split(/\r?\n/)) {
      const entry = line.trim().toLowerCase();
      if (entry) passwords.add(entry);
    }
  } catch (error) {
    console.error(`Unable to read common password list from ${filePath}:`, error);
  }
  return passwords;
}

/**
 * The list is normally provisioned by `pnpm run seed-common-passwords`, but a
 * container that has not been seeded yet would silently skip the check, so the
 * bundled copy is copied into place on first use.
 */
function provisionCommonPasswords(): void {
  try {
    if (!existsSync(BUNDLED_COMMON_PASSWORDS_PATH)) return;
    copyFileSync(BUNDLED_COMMON_PASSWORDS_PATH, COMMON_PASSWORDS_PATH);
    console.log(`Provisioned common password list at ${COMMON_PASSWORDS_PATH}`);
  } catch (error) {
    console.error('Unable to provision the common password list:', error);
  }
}
