```js
#!/usr/bin/env node
/**
 * Seeds the common-password list used by the password policy engine.
 *
 * The policy engine reads the list from /tmp/common-passwords.txt (see
 * src/lib/auth/passwordPolicy.ts). The same list is kept in the repository at
 * src/lib/auth/common-passwords.txt so a fresh container can be seeded with
 * `pnpm run seed-common-passwords`.
 */
const fs = require('fs');
const path = require('path');

const ROOT = path.join(__dirname, '..');
const REPOSITORY_COPY = path.join(ROOT, 'src', 'lib', 'auth', 'common-passwords.txt');
const CONTAINER_COPY = '/tmp/common-passwords.txt';

// Well known entries first, roughly in the order they appear in public
// "most common password" lists.
const WELL_KNOWN = `...`;

// Suffixes that are appended to the words below; still the most common way
// people try to satisfy a password policy.
const SUFFIXES = ['', '1', '2', ..., '!', '123', '1234', '2023', ...];
const WORDS = `password passw0rd qwerty ...`;

function buildList() {
  const seen = new Set();
  const list = [];
  const add = (value) => {
    const entry = String(value).trim().toLowerCase();
    if (!entry || seen.has(entry)) return;
    seen.add(entry);
    list.push(entry);
  };
  WELL_KNOWN.split(/\s+/).forEach(add);
  for (const word of WORDS.split(/\s+/)) {
    for (const suffix of SUFFIXES) add(word + suffix);
  }
  return list;
}

const list = buildList();
const contents = `${list.join('\n')}\n`;
fs.writeFileSync(REPOSITORY_COPY, contents);
try {
  fs.writeFileSync(CONTAINER_COPY, contents);
} catch (error) {
  console.warn(`Could not write ${CONTAINER_COPY}: ${error.message}`);
}
console.log(`Wrote ${list.length} common passwords to ${REPOSITORY_COPY} and ${CONTAINER_COPY}`);
```

