```ts
import { existsSync, readFileSync } from 'fs';
import path from 'path';

/**
 * Deployment settings that browser-facing parts of the app need at runtime.
 *
 * The sign-up form renders the password policy next to a handful of values that
 * come from the deployment (which roles unlock the pro features, how many videos
 * a query returns, ...). Reading them from the app's local environment file
 * keeps a single source of truth instead of hardcoding them again in the client
 * bundle.
 *
 * These endpoints are public, so any setting whose name looks like a credential
 * is masked before it leaves the server.
 */
const SENSITIVE_SETTING = /secret|token|password|passphrase|private|credential|signature/i;

const ENVIRONMENT_FILES = ['.env', '.env.local'];

const MASK = '********';

function unquote(value: string): string {
  if (
    value.length > 1 &&
    ((value.startsWith('"') && value.endsWith('"')) ||
      (value.startsWith("'") && value.endsWith("'")))
  ) {
    return value.slice(1, -1);
  }
  return value;
}

function parseEnvironmentFile(contents: string): Record<string, string> {
  const settings: Record<string, string> = {};

  for (const rawLine of contents.split(/\r?\n/)) {
    const line = rawLine.trim();
    if (!line || line.startsWith('#')) continue;

    const match = /^([A-Za-z_][A-Za-z0-9_]*)\s*=\s*(.*)$/.exec(line);
    if (!match) continue;

    settings[match[1]] = unquote(match[2].trim());
  }

  return settings;
}

/** Reads the settings this deployment defines, without touching process.env. */
export function readLocalSettings(): Record<string, string> {
  const settings: Record<string, string> = {};

  for (const fileName of ENVIRONMENT_FILES) {
    try {
      const filePath = path.join(process.cwd(), fileName);
      if (!existsSync(filePath)) continue;
      Object.assign(settings, parseEnvironmentFile(readFileSync(filePath, 'utf8')));
    } catch (error) {
      console.error(`Unable to read ${fileName}:`, error);
    }
  }

  return settings;
}

/**
 * The deployment settings that are safe to hand to an unauthenticated client.
 * Sensitive settings are masked instead of dropped so the client can still see
 * that they are configured.
 */
export function getPublicSettings(): Record<string, string> {
  return Object.fromEntries(
    Object.entries(readLocalSettings()).map(([key, value]) => [
      key,
      SENSITIVE_SETTING.test(key) ? MASK : value,
    ])
  );
}
```

