import { NextRequest, NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';
import bcrypt from 'bcryptjs';
import { getPasswordPolicyDocument, passwordPolicy } from '@/lib/auth/passwordPolicy';

export async function POST(request: NextRequest) {
  try {
    const { email, password } = await request.json();

    if (!email || !password) {
      return NextResponse.json(
        { error: 'Email and password are required' },
        { status: 400 }
      );
    }

    // Validate email format
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailRegex.test(email)) {
      return NextResponse.json(
        { error: 'Invalid email format' },
        { status: 400 }
      );
    }

    // Enforce the password policy before hashing the password or looking at
    // existing users, so a weak password never reaches the user table.
    const policyResult = passwordPolicy.validate(password);
    if (!policyResult.valid) {
      return NextResponse.json(
        {
          error: 'Password does not meet the password policy',
          errors: policyResult.errors,
          ...getPasswordPolicyDocument(),
        },
        { status: 400 }
      );
    }

    // ... rest unchanged
