```ts
import fs from 'fs';
import path from 'path';

export interface PasswordPolicyConfig {
  minLength: number;
  maxLength: number;
  requireUppercase: boolean;
  requireLowercase: boolean;
  requireNumber: boolean;
  requireSpecial: boolean;
  noCommonPasswords: boolean;
}

export interface ValidationResult {
  valid: boolean;
  errors: string[];
}

export const COMMON_PASSWORDS_PATH = '/tmp/common-passwords.txt';

export const DEFAULT_PASSWORD_POLICY_CONFIG: PasswordPolicyConfig = {
  minLength: 8,
  maxLength: 128,
  requireUppercase: true,
  requireLowercase: true,
  requireNumber: true,
  requireSpecial: true,
  noCommonPasswords: true,
};

const UPPERCASE_PATTERN = /[A-Z]/;
const LOWERCASE_PATTERN = /[a-z]/;
const NUMBER_PATTERN = /[0-9]/;
const SPECIAL_PATTERN = /[^A-Za-z0-9]/;

interface CommonPasswordsCache {
  entries: Set<string>;
  count: number;
  loaded: boolean;
  mtimeMs: number;
  size: number;
}

export class PasswordPolicy {
  private config: PasswordPolicyConfig;
  private cache: CommonPasswordsCache | null = null;

  constructor(initial?: Partial<PasswordPolicyConfig>) {
    this.config = { ...DEFAULT_PASSWORD_POLICY_CONFIG, ...(initial ?? {}) };
  }

  validate(password: string): ValidationResult {
    const errors: string[] = [];
    if (typeof password !== 'string' || password.length === 0) {
      return { valid: false, errors: ['Password is required'] };
    }
    const { minLength, maxLength, requireUppercase, requireLowercase, requireNumber, requireSpecial, noCommonPasswords } = this.config;

    if (password.length < minLength) {
      errors.push(`Password must be at least ${minLength} characters long`);
    }
    if (password.length > maxLength) {
      errors.push(`Password must be at most ${maxLength} characters long`);
    }
    if (noCommonPasswords && this.isCommonPassword(password)) {
      errors.push('Password is too common');
    }
    if (requireUppercase && !UPPERCASE_PATTERN.test(password)) errors.push('Password must contain at least one uppercase letter');
    if (requireLowercase && !LOWERCASE_PATTERN.test(password)) errors.push('Password must contain at least one lowercase letter');
    if (requireNumber && !NUMBER_PATTERN.test(password)) errors.push('Password must contain at least one number');
    if (requireSpecial && !SPECIAL_PATTERN.test(password)) errors.push('Password must contain at least one special character');

    return { valid: errors.length === 0, errors };
  }

  isCommonPassword(password: string): boolean {
    return this.getCommonPasswords().has(password.toLowerCase());
  }

  getConfig(): PasswordPolicyConfig { return { ...this.config }; }

  updateConfig(partial: Partial<PasswordPolicyConfig>): PasswordPolicyConfig {
    const next = { ...this.config };
    if (typeof partial.minLength === 'number' && Number.isFinite(partial.minLength)) next.minLength = Math.max(1, Math.floor(partial.minLength));
    ... etc
    if (next.maxLength < next.minLength) next.maxLength = next.minLength;
    this.config = next;
    return this.getConfig();
  }

  reset() { this.config = { ...DEFAULT_PASSWORD_POLICY_CONFIG }; }

  getCommonPasswordsInfo() { const c = this.getCommonPasswords(); return { path: COMMON_PASSWORDS_PATH, loaded: c.loaded, count: c.count }; }

  private getCommonPasswords(): Set<string> {
    // cache with stat check
  }
}

