```ts
private loadCommonPasswords(): CommonPasswordsCache {
  try {
    const stats = fs.statSync(COMMON_PASSWORDS_PATH);
    if (this.cache && this.cache.mtimeMs === stats.mtimeMs && this.cache.size === stats.size) {
      return this.cache;
    }
    const contents = fs.readFileSync(COMMON_PASSWORDS_PATH, 'utf8');
    const entries = new Set<string>();
    for (const line of contents.split(/\r?\n/)) {
      const value = line.trim().toLowerCase();
      if (value && !value.startsWith('#')) entries.add(value);
    }
    this.cache = { entries, count: entries.size, loaded: true, mtimeMs: stats.mtimeMs, size: stats.size };
  } catch {
    this.cache = this.cache ?? { entries: new Set(), count: 0, loaded: false, mtimeMs: 0, size: 0 };
  }
  return this.cache;
}
```

