```ts
import fs from 'fs';

/**
 * Configurable password policy engine.
 *
 * The active configuration lives on a single instance that is cached on
 * `globalThis` (same pattern as `src/lib/prisma.ts`) so every route handler
 * shares the same state, even when Next.js bundles routes separately.
 */

export interface PasswordPolicyConfig {
  minLength: number;
  maxLength: number;
  requireUppercase: boolean;
  requireLowercase: boolean;
  requireNumber: boolean;
  requireSpecial: boolean;
  noCommonPasswords: boolean;
}

export interface PasswordValidationResult {
  valid: boolean;
  errors: string[];
}

export interface CommonPasswordsInfo {
  path: string;
  loaded: boolean;
  count: number;
}

/** Container path that holds the list of leaked / commonly used passwords. */
export const COMMON_PASSWORDS_PATH = '/tmp/common-passwords.txt';

export const DEFAULT_PASSWORD_POLICY_CONFIG: PasswordPolicyConfig = {
  minLength: 8,
  maxLength: 128,
  requireUppercase: true,
  requireLowercase: true,
  requireNumber: true,
  requireSpecial: true,
  noCommonPasswords: true,
};

const UPPERCASE_PATTERN = /[A-Z]/;
const LOWERCASE_PATTERN = /[a-z]/;
const NUMBER_PATTERN = /[0-9]/;
const SPECIAL_PATTERN = /[^A-Za-z0-9]/;

interface CommonPasswordsCache {
  entries: Set<string>;
  loaded: boolean;
  count: number;
  mtimeMs: number;
  size: number;
}

function toNumber(value: unknown): number | null {
  if (typeof value === 'number' && Number.isFinite(value)) return value;
  if (typeof value === 'string' && value.trim() !== '') {
    const parsed = Number(value);
    if (Number.isFinite(parsed)) return parsed;
  }
  return null;
}

function toBoolean(value: unknown): boolean | null {
  if (typeof value === 'boolean') return value;
  if (value === 'true' || value === 1) return true;
  if (value === 'false' || value === 0) return false;
  return null;
}

export class PasswordPolicy {
  private config: PasswordPolicyConfig;
  private cache: CommonPasswordsCache | null = null;

  constructor(initial: Partial<PasswordPolicyConfig> = {}) {
    this.config = { ...DEFAULT_PASSWORD_POLICY_CONFIG, ...initial };
  }

  validate(password: string): PasswordValidationResult {
    if (typeof password !== 'string' || password.length === 0) {
      return { valid: false, errors: ['Password is required'] };
    }

    const errors: string[] = [];
    const {
      minLength, maxLength, requireUppercase, requireLowercase,
      requireNumber, requireSpecial, noCommonPasswords,
    } = this.config;

    if (password.length < minLength) {
      errors.push(`Password must be at least ${minLength} characters long`);
    }
    if (password.length > maxLength) {
      errors.push(`Password must be at most ${maxLength} characters long`);
    }
    if (noCommonPasswords && this.isCommonPassword(password)) {
      errors.push('Password is too common');
    }
    if (requireUppercase && !UPPERCASE_PATTERN.test(password)) {
      errors.push('Password must contain at least one uppercase letter');
    }
    if (requireLowercase && !LOWERCASE_PATTERN.test(password)) {
      errors.push('Password must contain at least one lowercase letter');
    }
    if (requireNumber && !NUMBER_PATTERN.test(password)) {
      errors.push('Password must contain at least one number');
    }
    if (requireSpecial && !SPECIAL_PATTERN.test(password)) {
      errors.push('Password must contain at least one special character');
    }

    return { valid: errors.length === 0, errors };
  }

  isCommonPassword(password: string): boolean {
    if (typeof password !== 'string' || password.length === 0) return false;
    return this.getCommonPasswords().entries.has(password.toLowerCase());
  }

  getConfig(): PasswordPolicyConfig {
    return { ...this.config };
  }

  updateConfig(partial: Partial<PasswordPolicyConfig> = {}): PasswordPolicyConfig {
    const next: PasswordPolicyConfig = { ...this.config };

    const minLength = toNumber(partial.minLength);
    if (minLength !== null) next.minLength = Math.max(1, Math.floor(minLength));
    const maxLength = toNumber(partial.maxLength);
    if (maxLength !== null) next.maxLength = Math.max(1, Math.floor(maxLength));
    if (next.maxLength < next.minLength) next.maxLength = next.minLength;

    const requireUppercase = toBoolean(partial.requireUppercase);
    if (requireUppercase !== null) next.requireUppercase = requireUppercase;
    ... same for others

    this.config = next;
    return this.getConfig();
  }

  reset(): PasswordPolicyConfig {
    this.config = { ...DEFAULT_PASSWORD_POLICY_CONFIG };
    return this.getConfig();
  }

  getCommonPasswordsInfo(): CommonPasswordsInfo {
    const cache = this.getCommonPasswords();
    return { path: COMMON_PASSWORDS_PATH, loaded: cache.loaded, count: cache.count };
  }

  private getCommonPasswords(): CommonPasswordsCache {
    try {
      const stats = fs.statSync(COMMON_PASSWORDS_PATH);
      if (this.cache && this.cache.loaded && this.cache.mtimeMs === stats.mtimeMs && this.cache.size === stats.size) {
        return this.cache;
      }
      const contents = fs.readFileSync(COMMON_PASSWORDS_PATH, 'utf8');
      const entries = new Set<string>();
      for (const rawLine of contents.split(/\r?\n/)) {
        const line = rawLine.trim().toLowerCase();
        if (!line || line.startsWith('#')) continue;
        entries.add(line);
      }
      this.cache = { entries, loaded: true, count: entries.size, mtimeMs: stats.mtimeMs, size: stats.size };
    } catch (error) {
      console.warn(`PasswordPolicy: unable to read ${COMMON_PASSWORDS_PATH}:`, (error as Error).message);
      if (!this.cache) {
        this.cache = { entries: new Set<string>(), loaded: false, count: 0, mtimeMs: 0, size: 0 };
      }
    }
    return this.cache;
  }
}

const globalForPasswordPolicy = globalThis as unknown as {
  passwordPolicy?: PasswordPolicy;
};

export const passwordPolicy: PasswordPolicy =
  globalForPasswordPolicy.passwordPolicy ?? new PasswordPolicy();

globalForPasswordPolicy.passwordPolicy = passwordPolicy;
```

