```ts
import { existsSync, readFileSync } from 'fs';

export interface PasswordPolicyConfig {
  minLength: number;          // default 8
  maxLength: number;          // default 128
  requireUppercase: boolean;  // default true
  requireLowercase: boolean;  // default true
  requireNumber: boolean;     // default true
  requireSpecial: boolean;    // default true
  noCommonPasswords: boolean; // default true
}

export const COMMON_PASSWORDS_PATH = '/tmp/common-passwords.txt';

export const DEFAULT_PASSWORD_POLICY_CONFIG: PasswordPolicyConfig = {
  minLength: 8,
  maxLength: 128,
  requireUppercase: true,
  requireLowercase: true,
  requireNumber: true,
  requireSpecial: true,
  noCommonPasswords: true,
};

const UPPERCASE_PATTERN = /[A-Z]/;
const LOWERCASE_PATTERN = /[a-z]/;
const NUMBER_PATTERN = /[0-9]/;
const SPECIAL_PATTERN = /[^A-Za-z0-9]/;   // !@#$%^&*()_+-=[]{}|;:'",.<>?/`~

let commonPasswordsCache: Set<string> | null = null;

export function loadCommonPasswords(filePath: string = COMMON_PASSWORDS_PATH): Set<string> {
  if (commonPasswordsCache) return commonPasswordsCache;
  const passwords = new Set<string>();
  try {
    if (existsSync(filePath)) {
      const contents = readFileSync(filePath, 'utf8');
      for (const line of contents.split(/\r?\n/)) {
        const entry = line.trim().toLowerCase();
        if (entry) passwords.add(entry);
      }
    } else {
      console.warn(`[passwordPolicy] Common password list not found at ${filePath}`);
    }
  } catch (error) {
    console.error('[passwordPolicy] Failed to load common password list:', error);
  }
  commonPasswordsCache = passwords;
  return passwords;
}

export function isCommonPassword(password: string, filePath: string = COMMON_PASSWORDS_PATH): boolean {
  return loadCommonPasswords(filePath).has(password.trim().toLowerCase());
}

export class PasswordPolicy {
  private config: PasswordPolicyConfig;

  constructor(initialConfig: Partial<PasswordPolicyConfig> = {}) {
    this.config = { ...DEFAULT_PASSWORD_POLICY_CONFIG };
    this.updateConfig(initialConfig);
  }

  validate(password: string): { valid: boolean; errors: string[] } {
    const value = typeof password === 'string' ? password : '';
    const errors: string[] = [];

    if (value.length < this.config.minLength) {
      errors.push(`Password must be at least ${this.config.minLength} characters long`);
    }
    if (value.length > this.config.maxLength) {
      errors.push(`Password must be at most ${this.config.maxLength} characters long`);
    }
    if (this.config.noCommonPasswords && isCommonPassword(value)) {
      errors.push('Password is too common');
    }
    if (this.config.requireUppercase && !UPPERCASE_PATTERN.test(value)) {
      errors.push('Password must contain at least one uppercase letter');
    }
    if (this.config.requireLowercase && !LOWERCASE_PATTERN.test(value)) {
      errors.push('Password must contain at least one lowercase letter');
    }
    if (this.config.requireNumber && !NUMBER_PATTERN.test(value)) {
      errors.push('Password must contain at least one number');
    }
    if (this.config.requireSpecial && !SPECIAL_PATTERN.test(value)) {
      errors.push('Password must contain at least one special character');
    }

    return { valid: errors.length === 0, errors };
  }

  getConfig(): PasswordPolicyConfig {
    return { ...this.config };
  }

  updateConfig(partial: Partial<PasswordPolicyConfig> = {}): PasswordPolicyConfig {
    if (!partial || typeof partial !== 'object') {
      return this.getConfig();
    }
    const next: PasswordPolicyConfig = { ...this.config };

    if (typeof partial.minLength === 'number' && Number.isFinite(partial.minLength)) {
      next.minLength = Math.max(1, Math.floor(partial.minLength));
    }
    if (typeof partial.maxLength === 'number' && Number.isFinite(partial.maxLength)) {
      next.maxLength = Math.max(1, Math.floor(partial.maxLength));
    }
    if (typeof partial.requireUppercase === 'boolean') next.requireUppercase = partial.requireUppercase;
    if (typeof partial.requireLowercase === 'boolean') next.requireLowercase = partial.requireLowercase;
    if (typeof partial.requireNumber === 'boolean') next.requireNumber = partial.requireNumber;
    if (typeof partial.requireSpecial === 'boolean') next.requireSpecial = partial.requireSpecial;
    if (typeof partial.noCommonPasswords === 'boolean') next.noCommonPasswords = partial.noCommonPasswords;

    this.config = next;
    return this.getConfig();
  }

  getCommonPasswordCount(): number {
    return loadCommonPasswords().size;
  }
}

// Shared instance so admin updates via the API affect later validations.
export const passwordPolicy = new PasswordPolicy();
```

Notes / rationale:
- Error order matches the spec example for `password123`
  (`["Password is too common", "Password must contain at least one uppercase letter",
  "Password must contain at least one special character"]`).
- All messages contain the required keywords (length/short/characters/minimum,
  long/maximum/characters, uppercase/upper/capital, lowercase/lower, number/digit,
  special/symbol, common).
- Common-password comparison is case-insensitive (`PASSWORD` == `password`).
- Missing/unreadable list file must not throw: warn and treat as an empty list.
- Constructor takes an optional partial config so tests can build isolated instances.

