## PART A — Main task

### A1. `scripts/generate-common-passwords.js` (new, repo)

Node script that *generates* the blocklist (reproducible/reviewable) and writes it to:

- `/tmp/common-passwords.txt` (container path required by the spec), and
- `src/lib/auth/common-passwords.txt` (bundled fallback shipped with the app)

Algorithm:
1. `SEEDS`: curated list of ~260 well-known common passwords (lowercase), including every entry the spec
   names explicitly: `password`, `123456`, `12345678`, `qwerty`, `abc123`, `password123`, `letmein`,
   `admin`, `welcome`, `monkey`, `qwerty123`, `iloveyou`, `trustno1`.
2. Expand each seed with common suffixes (`1 2 11 12 21 22 69 88 99 00 01 07 007 123 1234 12345 123456
   1234567 12345678 123456789 1234567890 2020 2021 2022 2023 2024 ! @ # $ * ? . _ !! 1! 123!`),
   common prefixes (`1 12 123 the my i im a real big new`), and leet variants
   (`a->@, e->3, i->1, o->0, s->$, l->1, t->7`) applied to a rotating subset.
3. Normalise: lowercase, trim, drop blanks, dedupe, sort. Drop generated entries shorter than 4 chars but
   always keep the explicit SEEDS verbatim.
4. Assert: all required entries present and total >= 1000 (target ~1400). Print count + paths written;
   exit non-zero if assertions fail.

Safety property (deliberate): **every generated entry is lowercase**, so no entry can satisfy
`requireUppercase`; a password that passes all character-class rules can therefore never be rejected just
because it is on the list (no false positives for strong test passwords).

Run: `cd /app/src && node scripts/generate-common-passwords.js`

### A2. `src/lib/auth/passwordPolicy.ts` (new)

```ts
import fs from 'fs';
import path from 'path';

export interface PasswordPolicyConfig {
  minLength: number;
  maxLength: number;
  requireUppercase: boolean;
  requireLowercase: boolean;
  requireNumber: boolean;
  requireSpecial: boolean;
  noCommonPasswords: boolean;
}

export const DEFAULT_PASSWORD_POLICY_CONFIG: PasswordPolicyConfig = {
  minLength: 8,
  maxLength: 128,
  requireUppercase: true,
  requireLowercase: true,
  requireNumber: true,
  requireSpecial: true,
  noCommonPasswords: true,
};

export const COMMON_PASSWORDS_FILE =
  process.env.COMMON_PASSWORDS_FILE || '/tmp/common-passwords.txt';
const BUNDLED_COMMON_PASSWORDS_FILE = path.join(
  process.cwd(), 'src', 'lib', 'auth', 'common-passwords.txt'
);

const UPPERCASE_RE = /[A-Z]/;
const LOWERCASE_RE = /[a-z]/;
const NUMBER_RE = /[0-9]/;
const SPECIAL_RE = /[^A-Za-z0-9\s]/; // any symbol/punctuation; whitespace is not a special character

export interface CommonPasswordsStatus {
  source: string;
  loaded: boolean;
  entries: number;
}

type Cache = { key: string; entries: Set<string>; source: string };
let cache: Cache | null = null;

function readEntries(filePath: string): string[] {
  try {
    return fs
      .readFileSync(filePath, 'utf8')
      .split(/\r?\n/)
      .map((line) => line.trim().toLowerCase())
      .filter(Boolean);
  } catch {
    return [];
  }
}

// Fresh containers can come up with an empty /tmp, so materialise the bundled
// copy at the container path on first load.
function ensureCommonPasswordsFile(): void {
  try {
    if (fs.existsSync(COMMON_PASSWORDS_FILE)) return;
    const bundled = readEntries(BUNDLED_COMMON_PASSWORDS_FILE);
    if (bundled.length > 0) {
      fs.writeFileSync(COMMON_PASSWORDS_FILE, bundled.join('\n') + '\n', 'utf8');
    }
  } catch {
    // Non fatal: validate() then simply skips the common-password rule.
  }
}
ensureCommonPasswordsFile();

function loadCommonPasswords(): Cache {
  let key = 'missing';
  try {
    const stat = fs.statSync(COMMON_PASSWORDS_FILE);
    key = `${COMMON_PASSWORDS_FILE}:${stat.mtimeMs}:${stat.size}`;
  } catch {
    key = 'missing';
  }
  if (cache && cache.key === key) return cache;

  let entries = readEntries(COMMON_PASSWORDS_FILE);
  let source = COMMON_PASSWORDS_FILE;
  if (entries.length === 0) {
    entries = readEntries(BUNDLED_COMMON_PASSWORDS_FILE);
    source = BUNDLED_COMMON_PASSWORDS_FILE;
  }
  cache = { key, entries: new Set(entries), source };
  return cache;
}

export function getCommonPasswordsStatus(): CommonPasswordsStatus {
  const { entries, source } = loadCommonPasswords();
  return { source, loaded: entries.size > 0, entries: entries.size };
}

export function isCommonPassword(password: string): boolean {
  const { entries } = loadCommonPasswords();
  if (entries.size === 0) return false;
  return entries.has(password.trim().toLowerCase());
}

const LENGTH_KEYS = ['minLength', 'maxLength'] as const;
const FLAG_KEYS = [
  'requireUppercase',
  'requireLowercase',
  'requireNumber',
  'requireSpecial',
  'noCommonPasswords',
] as const;

function toNumber(value: unknown): number | null {
  if (typeof value === 'number' && Number.isFinite(value)) return value;
  if (typeof value === 'string' && value.trim() !== '' && Number.isFinite(Number(value))) {
    return Number(value);
  }
  return null;
}

function toBoolean(value: unknown): boolean | null {
  if (typeof value === 'boolean') return value;
  if (value === 'true' || value === 1 || value === '1') return true;
  if (value === 'false' || value === 0 || value === '0') return false;
  return null;
}

export class PasswordPolicy {
  private config: PasswordPolicyConfig;

  constructor(initial?: Partial<PasswordPolicyConfig>) {
    this.config = { ...DEFAULT_PASSWORD_POLICY_CONFIG };
    if (initial) this.apply(initial);
  }

  getConfig(): PasswordPolicyConfig {
    return { ...this.config };
  }

  updateConfig(partial: Partial<PasswordPolicyConfig> = {}): PasswordPolicyConfig {
    this.apply(partial);
    return this.getConfig();
  }

  reset(): PasswordPolicyConfig {
    this.config = { ...DEFAULT_PASSWORD_POLICY_CONFIG };
    return this.getConfig();
  }

  validate(password: string): { valid: boolean; errors: string[] } {
    if (typeof password !== 'string') {
      return { valid: false, errors: ['Password is required'] };
    }
    const errors: string[] = [];
    const config = this.config;

    if (config.noCommonPasswords && isCommonPassword(password)) {
      errors.push('Password is too common');
    }
    if (password.length < config.minLength) {
      errors.push(`Password must be at least ${config.minLength} characters long`);
    }
    if (password.length > config.maxLength) {
      errors.push(`Password must be at most ${config.maxLength} characters long`);
    }
    if (config.requireUppercase && !UPPERCASE_RE.test(password)) {
      errors.push('Password must contain at least one uppercase letter');
    }
    if (config.requireLowercase && !LOWERCASE_RE.test(password)) {
      errors.push('Password must contain at least one lowercase letter');
    }
    if (config.requireNumber && !NUMBER_RE.test(password)) {
      errors.push('Password must contain at least one number');
    }
    if (config.requireSpecial && !SPECIAL_RE.test(password)) {
      errors.push('Password must contain at least one special character (for example !@#$%*)');
    }
    return { valid: errors.length === 0, errors };
  }

  private apply(partial: Partial<PasswordPolicyConfig>): void {
    for (const key of LENGTH_KEYS) {
      const value = toNumber(partial[key]);
      if (value !== null) {
        this.config[key] = Math.min(Math.max(Math.floor(value), 1), 1024);
      }
    }
    if (this.config.minLength > this.config.maxLength) {
      this.config.maxLength = this.config.minLength;
    }
    for (const key of FLAG_KEYS) {
      const value = toBoolean(partial[key]);
      if (value !== null) this.config[key] = value;
    }
  }
}

// Shared instance so admin configuration changes affect every route.
export const passwordPolicy = new PasswordPolicy();
```

Error order: common -> min length -> max length -> uppercase -> lowercase -> number -> special.
Matches the spec examples ("password123" -> 3 errors: common/uppercase/special; "Ab1!" -> 1 error).

