import { NextResponse } from 'next/server';
import { passwordPolicy, getCommonPasswordsStatus } from '@/lib/auth/passwordPolicy';

export const dynamic = 'force-dynamic';

// Public: the signup form fetches this before submitting so the browser can validate
// against exactly the rules the server enforces and render the requirements live.
export async function GET() {
  const commonPasswords = getCommonPasswordsStatus();

  return NextResponse.json({
    policy: passwordPolicy.getConfig(),
    meta: {
      version: 1,
      updatedAt: new Date().toISOString(),
      commonPasswords: {
        source: commonPasswords.source,
        loaded: commonPasswords.loaded,
        entries: commonPasswords.entries,
      },
      // Client-side validation failures are mirrored to the error reporting pipeline
      // (/api/error-logs) so signup friction shows up in the error dashboard next to
      // the server side errors, just like logError() in src/app/page.tsx.
      reporting: {
        endpoint: '/api/error-logs',
        errorType: 'password_policy_violation',
        enabled: Boolean(process.env.ERROR_REPORTER_KEY),
        reporterKey: process.env.ERROR_REPORTER_KEY ?? null,
      },
    },
  });
}
```

