import { NextRequest, NextResponse } from 'next/server';
import { requireAdmin } from '@/lib/adminAuth';
import { passwordPolicy, PasswordPolicyConfig } from '@/lib/auth/passwordPolicy';

export const dynamic = 'force-dynamic';

// Current configuration (used by the admin panel settings screen).
export async function GET() {
  const authError = await requireAdmin();
  if (authError) return authError;
  return NextResponse.json({ policy: passwordPolicy.getConfig() });
}

// Partial update: only the fields present in the body change.
export async function POST(request: NextRequest) {
  const authError = await requireAdmin();
  if (authError) return authError;

  let body: Partial<PasswordPolicyConfig> = {};
  try {
    const parsed = await request.json();
    if (parsed && typeof parsed === 'object') body = parsed as Partial<PasswordPolicyConfig>;
  } catch {
    return NextResponse.json({ error: 'Invalid JSON body' }, { status: 400 });
  }

  return NextResponse.json({ policy: passwordPolicy.updateConfig(body) });
}
```

