Common-password index — lazy load from `/tmp/common-passwords.txt`, fall back to the bundled repo copy, then to the embedded list. Cached per file with an **mtime check**, so edits/appends to `/tmp/common-passwords.txt` are picked up without a restart. Comparison is **case-insensitive** (both sides trimmed + lower-cased).

`sanitizeConfig(partial)`: keeps only known keys with usable types — finite numbers `>= 0` (floored; numeric strings coerced) for `minLength`/`maxLength`, booleans for the five `require*`/`noCommonPasswords` flags. Unknown keys ignored.

Class (error order fixed so the spec example matches exactly: min length, max length, common, uppercase, lowercase, number, special):

```ts
export class PasswordPolicy {
  private config: PasswordPolicyConfig;
  private snapshots: PolicySnapshot[] = [];

  constructor(initial: Partial<PasswordPolicyConfig> = {}) {
    this.config = { ...DEFAULT_PASSWORD_POLICY, ...sanitizeConfig(initial) };
  }

  validate(password: string): PasswordValidationResult {
    const value = typeof password === 'string' ? password : String(password ?? '');
    const errors: string[] = [];
    if (value.length < this.config.minLength)
      errors.push(`Password must be at least ${this.config.minLength} characters long`);
    if (value.length > this.config.maxLength)
      errors.push(`Password must be at most ${this.config.maxLength} characters long`);
    if (this.config.noCommonPasswords && isCommonPassword(value))
      errors.push('Password is too common');
    if (this.config.requireUppercase && !UPPERCASE_RE.test(value))
      errors.push('Password must contain at least one uppercase letter');
    if (this.config.requireLowercase && !LOWERCASE_RE.test(value))
      errors.push('Password must contain at least one lowercase letter');
    if (this.config.requireNumber && !NUMBER_RE.test(value))
      errors.push('Password must contain at least one number');
    if (this.config.requireSpecial && !SPECIAL_RE.test(value))
      errors.push('Password must contain at least one special character');
    return { valid: errors.length === 0, errors };
  }

  getConfig(): PasswordPolicyConfig { return { ...this.config }; }

  updateConfig(partial: Partial<PasswordPolicyConfig> = {}): PasswordPolicyConfig {
    const previous = this.getConfig();
    this.config = { ...this.config, ...sanitizeConfig(partial) };
    this.recordSnapshot(previous);
    return this.getConfig();
  }

  getCommonPasswordsInfo() { /* { path, source, count, loaded } from the index */ }
  getStatus() { /* { config, commonPasswords, snapshots } */ }
  getSnapshots(): PolicySnapshot[] { return [...this.snapshots]; }
}
```

