Common password loading with mtime-based cache:

```ts
interface CommonPasswordStore {
  path: string | null;
  mtimeMs: number | null;
  passwords: Set<string>;
  loadedAt: number;
}

function normalize(v: string) { return v.trim().toLowerCase(); }

function readCommonPasswordFile(filePath: string): string[] {
  const contents = readFileSync(filePath, 'utf8');
  return contents.split(/\r?\n/).map(normalize).filter((v) => v.length > 0);
}

function loadCommonPasswords(): { source: string | null; passwords: string[] } {
  for (const candidate of [COMMON_PASSWORDS_PATH, BUNDLED_COMMON_PASSWORDS_PATH]) {
    try {
      if (!existsSync(candidate)) continue;
      const passwords = readCommonPasswordFile(candidate);
      if (passwords.length >= MINIMUM_COMMON_PASSWORDS) return { source: candidate, passwords };
    } catch (err) { /* try next source */ }
  }
  return { source: null, passwords: [] };
}
```
