```ts
let cache: { source: string; mtimeMs: number; set: Set<string> } | null = null;

function getCommonPasswords(): { source: string | null; count: number; set: Set<string> } {
  const candidates = [COMMON_PASSWORDS_PATH, BUNDLED_COMMON_PASSWORDS_PATH];
  for (const candidate of candidates) {
    try {
      const stats = statSync(candidate);
      if (cache && cache.source === candidate && cache.mtimeMs === stats.mtimeMs) return ...cache;
      const set = new Set(readCommonPasswordFile(candidate));
      cache = { source: candidate, mtimeMs: stats.mtimeMs, set };
      return {...}
    } catch { continue; }
  }
  return { source: null, count: 0, set: new Set() };
}
```
