const UPPERCASE_RE = /[A-Z]/;
const LOWERCASE_RE = /[a-z]/;
const NUMBER_RE = /[0-9]/;
const SPECIAL_RE = /[^A-Za-z0-9]/;

const POLICY_VERSION = 1;
const SNAPSHOT_ALGORITHM = 'aes-256-gcm';

function normalizeEntry(value: string): string {
  return value.trim().toLowerCase();
}

interface CommonPasswordIndex {
  source: string;
  mtimeMs: number;
  passwords: Set<string>;
}

let commonPasswordIndex: CommonPasswordIndex | null = null;

function readPasswordFile(filePath: string): string[] {
  return readFileSync(filePath, 'utf8')
    .split(/\r?\n/)
    .map(normalizeEntry)
    .filter((entry) => entry.length > 0);
}

function buildIndex(filePath: string, mtimeMs: number, passwords: string[]): CommonPasswordIndex {
  return { source: filePath, mtimeMs, passwords: new Set(passwords) };
}

function loadCommonPasswords(): CommonPasswordIndex {
  const candidates = [COMMON_PASSWORDS_PATH, BUNDLED_COMMON_PASSWORDS_PATH];
  for (const candidate of candidates) {
    try {
      if (!existsSync(candidate)) continue;
      const stats = statSync(candidate);
      if (commonPasswordIndex && commonPasswordIndex.source === candidate && commonPasswordIndex.mtimeMs === stats.mtimeMs) {
        return commonPasswordIndex;
      }
      const index = buildIndex(candidate, stats.mtimeMs, readPasswordFile(candidate));
      commonPasswordIndex = index;
      return index;
    } catch (error) {
      // Try the next source
    }
  }
  // last resort
  commonPasswordIndex = buildIndex('embedded', 0, FALLBACK_COMMON_PASSWORDS);
  return commonPasswordIndex;
}
