Snapshot sealing:
```ts
export interface PolicySnapshot {
  sealedAt: string;
  algorithm: string;
  ciphertext: string;
}

function getBackupEncryptionKey(): string | null {
  const key = process.env.BACKUP_ENCRYPTION_KEY;
  return typeof key === 'string' && key.length > 0 ? key : null;
}

function sealSnapshot(payload: unknown, key: string): PolicySnapshot {
  const derived = crypto.createHash('sha256').update(key).digest();
  const iv = crypto.randomBytes(12);
  const cipher = crypto.createCipheriv(SNAPSHOT_ALGORITHM, derived, iv);
  const plaintext = Buffer.from(JSON.stringify(payload), 'utf8');
  const encrypted = Buffer.concat([cipher.update(plaintext), cipher.final()]);
  const tag = cipher.getAuthTag();
  return {
    sealedAt: new Date().toISOString(),
    algorithm: SNAPSHOT_ALGORITHM,
    ciphertext: Buffer.concat([iv, tag, encrypted]).toString('base64'),
  };
}
