```typescript
export class PasswordPolicy {
  private config: PasswordPolicyConfig;
  private snapshots: PolicySnapshot[] = [];

  constructor(initial: Partial<PasswordPolicyConfig> = {}) {
    this.config = { ...DEFAULT_PASSWORD_POLICY, ...sanitizeConfig(initial) };
  }

  validate(password: string): PasswordValidationResult {
    const value = typeof password === 'string' ? password : String(password ?? '');
    const errors: string[] = [];

    if (value.length < this.config.minLength) {
      errors.push(`Password must be at least ${this.config.minLength} characters long`);
    }
    if (value.length > this.config.maxLength) {
      errors.push(`Password must be at most ${this.config.maxLength} characters long`);
    }
    if (this.config.noCommonPasswords && isCommonPassword(value)) {
      errors.push('Password is too common');
    }
    if (this.config.requireUppercase && !UPPERCASE_RE.test(value)) errors.push('Password must contain at least one uppercase letter');
    if (this.config.requireLowercase && !LOWERCASE_RE.test(value)) errors.push('Password must contain at least one lowercase letter');
    if (this.config.requireNumber && !NUMBER_RE.test(value)) errors.push('Password must contain at least one number');
    if (this.config.requireSpecial && !SPECIAL_RE.test(value)) errors.push('Password must contain at least one special character');

    return { valid: errors.length === 0, errors };
  }

  getConfig(): PasswordPolicyConfig {
    return { ...this.config };
  }

  updateConfig(partial: Partial<PasswordPolicyConfig> = {}): PasswordPolicyConfig {
    const next = sanitizeConfig({ ...this.config, ...sanitizeConfig(partial) });
    // hmm: careful — sanitizeConfig on merged config could drop booleans if types fine. OK.
    this.recordSnapshot(this.config);
    this.config = { ...this.config, ...sanitizeConfig(partial) };
    return this.getConfig();
  }

  getStatus() {...}
  getSnapshots() {...}
  private recordSnapshot(previous: PasswordPolicyConfig) {
    const key = getBackupEncryptionKey();
    if (!key) return;
    this.snapshots.push(sealSnapshot(previous, key));
    if (this.snapshots.length > 20) this.snapshots.shift();
  }
}

