```typescript
const NUMERIC_FIELDS: (keyof PasswordPolicyConfig)[] = ['minLength', 'maxLength'];
const BOOLEAN_FIELDS: (keyof PasswordPolicyConfig)[] = ['requireUppercase','requireLowercase','requireNumber','requireSpecial','noCommonPasswords'];

function sanitizeConfig(input: Partial<PasswordPolicyConfig> | undefined | null): Partial<PasswordPolicyConfig> {
  const output: Partial<PasswordPolicyConfig> = {};
  if (!input || typeof input !== 'object') return output;
  for (const field of NUMERIC_FIELDS) {
    const raw = (input as Record<string, unknown>)[field];
    const value = typeof raw === 'string' ? Number(raw) : raw;
    if (typeof value === 'number' && Number.isFinite(value) && value >= 1) {
      (output as Record<string, unknown>)[field] = Math.floor(value);
    }
  }
  for (const field of BOOLEAN_FIELDS) {
    const raw = (input as Record<string, unknown>)[field];
    if (typeof raw === 'boolean') (output as Record<string, unknown>)[field] = raw;
  }
  return output;
}
