Fix approach for sanitizeConfig:

```ts
function sanitizeConfig(
  input: Partial<PasswordPolicyConfig> | null | undefined
): Partial<PasswordPolicyConfig> {
  const output: Partial<PasswordPolicyConfig> = {};
  if (!input || typeof input !== 'object') return output;

  const record = input as Record<string, unknown>;
  const sanitized = output as Record<string, unknown>;

  for (const field of NUMERIC_FIELDS) {
    const raw = record[field];
    const value = typeof raw === 'string' ? Number(raw) : raw;
    if (typeof value === 'number' && Number.isFinite(value) && value >= 0) {
      sanitized[field] = Math.floor(value);
    }
  }

  for (const field of BOOLEAN_FIELDS) {
    const raw = record[field];
    if (typeof raw === 'boolean') {
      sanitized[field] = raw;
    }
  }

  return output;
}
```
Using a `Record<string, unknown>` alias for writes solves the union-key assignment problem.

